// -- CHIAMATE A SUPABASE --
// Ogni chiamata dell'area riservata passa da sbFetch: porta sempre il token della sessione
// (mai la chiave anonima, che resta solo nell'header apikey) e non rompe la pagina.
// Una lettura negata o fallita risponde con res.ok falso e corpo [], quindi res.json() è sicuro.
// Una scrittura negata avvisa l'utente; { silenzioso:true } serve per log e sfondo.
function sbRisposta(status, corpo) {
  return new Response(corpo, { status, headers: { 'Content-Type': 'application/json' } });
}

async function sbFetch(url, opz) {
  const { silenzioso, ...richiesta } = opz || {};
  const lettura = !richiesta.method || richiesta.method === 'GET';
  let token = null;
  try { token = await auToken(); } catch(e) {}
  if (!token) {
    if (!lettura && !silenzioso) sbAvviso('Sessione scaduta: esci e rientra.');
    return sbRisposta(401, lettura ? '[]' : '{}');
  }
  richiesta.headers = Object.assign({}, richiesta.headers, { 'apikey': SUPA_KEY, 'Authorization': 'Bearer ' + token });
  let res;
  try { res = await fetch(url, richiesta); }
  catch(e) {
    if (!lettura && !silenzioso) sbAvviso('Connessione assente: operazione non eseguita.');
    return sbRisposta(503, lettura ? '[]' : '{}');
  }
  if (lettura) {
    if (!res.ok) return sbRisposta(res.status, '[]');
    if (res.status === 204 || !(await res.clone().text())) return new Response('[]', { status: 200, headers: res.headers });
  } else if ((res.status === 401 || res.status === 403) && !silenzioso) {
    sbAvviso('Operazione non consentita.');
  }
  return res;
}

// Dentro un try: passa al catch della sezione, che mostra "Non disponibile."
function sbOk(res) { if (!res.ok) throw new Error('Non disponibile.'); }

let sbAvvisoTimer = null;
function sbAvviso(testo) {
  let el = document.getElementById('sbAvviso');
  if (!el) {
    el = document.createElement('div');
    el.id = 'sbAvviso';
    el.className = 'sb-avviso';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
  }
  el.textContent = testo;
  el.hidden = false;
  clearTimeout(sbAvvisoTimer);
  sbAvvisoTimer = setTimeout(() => { el.hidden = true; }, 5000);
}

// -- FILE NEI BUCKET PRIVATI --
// Nel database un file è "bucket/percorso"; i record vecchi hanno l'URL pubblico intero e si
// leggono uguale. I link durano un'ora e si firmano in blocco.
const SB_BUCKET_PRIVATI = ['documenti','attestati','documenti-mezzi','documenti-tlc','mappe-postazioni','segnalazioni','eventi','foto-volontari'];
const SB_FILE_DURATA = 3600;

function sbPercorso(bucket, path) {
  return SB_BUCKET_PRIVATI.includes(bucket) ? bucket + '/' + path : SUPA_URL + '/storage/v1/object/public/' + bucket + '/' + path;
}

function sbRif(valore) {
  const s = String(valore || '').trim();
  if (/^https?:/i.test(s)) {
    const m = s.match(/\/storage\/v1\/object\/(?:public\/|sign\/|authenticated\/)?([^/?]+)\/([^?#]+)/);
    if (!m) return null;
    try { return { bucket: m[1], path: decodeURIComponent(m[2]) }; } catch(e) { return { bucket: m[1], path: m[2] }; }
  }
  const i = s.indexOf('/');
  return i > 0 ? { bucket: s.slice(0, i), path: s.slice(i + 1) } : null;
}

// Restituisce Map(valore del database → link utilizzabile, null se il file non è disponibile)
async function sbFirma(valori) {
  const link = new Map(), perBucket = {};
  [...new Set((valori || []).filter(Boolean))].forEach(v => {
    const r = sbRif(v);
    if (r && SB_BUCKET_PRIVATI.includes(r.bucket)) (perBucket[r.bucket] = perBucket[r.bucket] || []).push({ v, path: r.path });
    else link.set(v, /^https?:/i.test(v) ? v : null);
  });
  await Promise.all(Object.keys(perBucket).map(async bucket => {
    const voci = perBucket[bucket];
    try {
      if (!(await auToken())) throw new Error('sessione assente');
      const { data, error } = await auClient.storage.from(bucket).createSignedUrls(voci.map(x => x.path), SB_FILE_DURATA);
      if (error) throw error;
      voci.forEach((x, i) => { const d = data[i]; link.set(x.v, d && !d.error && d.signedUrl ? d.signedUrl : null); });
    } catch(e) { voci.forEach(x => link.set(x.v, null)); }
  }));
  return link;
}

async function sbUrlFile(valore) { return (await sbFirma([valore])).get(valore) || null; }

// Mette in r._file il link firmato di r[campo]
async function sbFirmaRighe(righe, campo) {
  const link = await sbFirma(righe.map(r => r[campo]));
  righe.forEach(r => { r._file = link.get(r[campo]) || null; });
}

// Avatar del volontario: foto firmata in v._file (sbFirmaRighe su foto_url), altrimenti iniziali.
// Anche un'immagine che non si carica torna alle iniziali.
function sbAvatar(v, cls) {
  const ini = escapeHtmlNav(((v.cognome || '?')[0] + (v.nome || '?')[0]).toUpperCase());
  return v._file
    ? '<img src="' + escapeHtmlNav(v._file) + '" class="' + cls + '" alt="" data-ini="' + ini + '" onerror="sbAvatarRotto(this)">'
    : '<span class="' + cls + '">' + ini + '</span>';
}
function sbAvatarRotto(img) {
  const s = document.createElement('span');
  s.className = img.className;
  s.textContent = img.dataset.ini;
  img.replaceWith(s);
}

function sbLinkFile(rif, url, scarica) {
  // link non firmato (es. sessione in rinnovo al ritorno dalla fotocamera): si firma al clic
  if (!url && rif) return '<a href="#" class="btn sm" data-sb-file="' + escapeHtmlNav(rif) + '" data-sb-t="0">Apri</a>';
  if (!url) return '<span class="sub">File non disponibile</span>';
  const attr = ' class="btn sm" data-sb-file="' + escapeHtmlNav(rif) + '" data-sb-t="' + Date.now() + '"';
  let h = '<a href="' + escapeHtmlNav(url) + '" target="_blank" rel="noopener"' + attr + '>Apri</a>';
  if (scarica) h += '<a href="' + escapeHtmlNav(url + (url.includes('?') ? '&' : '?') + 'download=' + encodeURIComponent(scarica)) + '"' + attr + '>Scarica</a>';
  return h;
}

// Un link scaduto (pagina aperta da tempo) si rigenera al clic
document.addEventListener('click', async e => {
  const a = e.target.closest && e.target.closest('a[data-sb-file]');
  if (!a || Date.now() - Number(a.dataset.sbT) < (SB_FILE_DURATA - 300) * 1000) return;
  e.preventDefault();
  const finestra = window.open('', '_blank');
  const url = await sbUrlFile(a.dataset.sbFile);
  if (url) finestra.location = url;
  else { finestra.close(); sbAvviso('File non disponibile.'); }
});

async function sbEliminaFile(valore) {
  const r = sbRif(valore);
  if (!r) return;
  await sbFetch(SUPA_URL + '/storage/v1/object/' + r.bucket + '/' + r.path.split('/').map(encodeURIComponent).join('/'), { method: 'DELETE', headers: H, silenzioso: true });
}

