function navIc(n, s) { s = s || 22; return '<svg viewBox="0 0 24 24" width="'+s+'" height="'+s+'" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(NAV_IC[n]||NAV_IC.more)+'"/></svg>'; }
function _navRuolo() {
  if (!currentUser) return '';
  return currentUser.tipo_accesso === 'volontario' || currentUser.tipo_accesso === 'master' ? currentUser.tipo_accesso : 'standard';
}
function _navVoci() {
  var ruolo = _navRuolo();
  return NAV_VOCI.filter(function(x) {
    var b = document.getElementById(x.id);
    return b && b.style.display !== 'none' && x.ruoli.indexOf(ruolo) >= 0;
  });
}
function _navAttiva(x) { return document.getElementById(x.id).classList.contains('active'); }
function _navBadge(x) { var s = document.getElementById(x.id).querySelector('.si-badge.show'); return s && s.textContent ? '<span class="nbadge">'+s.textContent+'</span>' : ''; }
function _navAltroOn() { return _navVoci().some(function(x){ return x.sez && _navAttiva(x); }); }
function _navAltroHtml() {
  var voci = _navVoci().filter(function(x){ return x.sez; });
  var h = '';
  voci.map(function(x){ return x.sez; }).filter(function(g, i, a){ return a.indexOf(g) === i; }).forEach(function(g) {
    h += '<div class="grp">'+g+'</div><div class="pgrid">' + voci.filter(function(x){ return x.sez === g; }).map(function(x) {
      return '<button class="pitem'+(_navAttiva(x)?' on':'')+'" onclick="navVai(\''+x.id+'\')">'+navIc(x.ic,20)+'<span>'+x.label+'</span>'+_navBadge(x)+'</button>';
    }).join('') + '</div>';
  });
  h += '<div class="grp">Account</div><div class="pgrid"><button class="pitem" onclick="chiudiAltro();logout()">'+navIc('logout',20)+'<span>Esci</span></button></div>';
  return h;
}
function renderNav() {
  var top = document.getElementById('topnav'), bot = document.getElementById('bottomnav');
  if (!top || !bot) return;
  var barra = _navVoci().filter(function(x){ return !x.sez; });
  top.innerHTML = barra.map(function(x) {
    return '<button class="tab'+(_navAttiva(x)?' on':'')+'" onclick="navVai(\''+x.id+'\')">'+x.label+'</button>';
  }).join('');
  var ab = document.getElementById('altroBtn');
  if (ab) ab.classList.toggle('on', _navAltroOn());
  bot.innerHTML = barra.map(function(x) {
    return '<button class="bt'+(_navAttiva(x)?' on':'')+'" onclick="navVai(\''+x.id+'\')"><span class="pill-i">'+navIc(x.ic)+'</span>'+x.label+'</button>';
  }).join('') + '<button class="bt'+(_navAltroOn()?' on':'')+'" onclick="toggleAltro()"><span class="pill-i">'+navIc('more')+'</span>Altro</button>';
  var pop = document.getElementById('altroPop');
  if (pop && !pop.hidden) pop.innerHTML = _navAltroHtml();
}
function navVai(id) { chiudiAltro(); var b = document.getElementById(id); if (b) b.click(); window.scrollTo(0, 0); }
function toggleAltro() {
  if (window.matchMedia('(max-width:899px)').matches) {
    var s = document.getElementById('altroSheet');
    s.innerHTML = '<div class="sheet" role="dialog" aria-modal="true" aria-label="Altro"><div class="shead"><h2>Altro</h2><button class="x" onclick="chiudiAltro()" aria-label="Chiudi">'+navIc('close',18)+'</button></div><div class="sbody">'+_navAltroHtml()+'</div></div>';
    s.hidden = false;
    return;
  }
  var p = document.getElementById('altroPop');
  if (p.hidden) { p.innerHTML = _navAltroHtml(); p.hidden = false; } else p.hidden = true;
}
function chiudiAltro() {
  var p = document.getElementById('altroPop'), s = document.getElementById('altroSheet');
  if (p) p.hidden = true;
  if (s) { s.hidden = true; s.innerHTML = ''; }
}
function renderWho() {
  var n = document.getElementById('whoName'), a = document.getElementById('whoAv');
  if (!n || !currentUser) return;
  // nome + cognome quando sono separati; il vecchio accesso ha un solo campo
  var proprio = whoMaiuscole(currentUser.nomeProprio), cognome = whoMaiuscole(currentUser.cognome);
  var nome = (proprio + ' ' + cognome).trim() || whoMaiuscole(currentUser.nome);
  var iniziali = proprio && cognome ? proprio[0] + cognome[0] : nome.split(' ').map(function(x){ return x[0] || ''; }).join('').slice(0,2);
  var ruolo = { master:'Master', standard:'Staff', volontario:'Volontario' }[_navRuolo()];
  a.textContent = iniziali.toUpperCase() || '—';
  n.innerHTML = '<span>' + escapeHtmlNav(nome) + '<small>' + ruolo + '</small></span>';
}
function whoMaiuscole(s) {
  s = String(s || '').trim();
  if (s.indexOf('@') !== -1) return s; // email al posto del nome
  return s.toLowerCase().replace(/(^|[\s'’-])(\p{L})/gu, function(m, p, c) { return p + c.toUpperCase(); });
}
function escapeHtmlNav(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
document.addEventListener('click', function(e) {
  var p = document.getElementById('altroPop');
  if (p && !p.hidden && !e.target.closest('#altroPop') && !e.target.closest('.tab')) p.hidden = true;
});
document.addEventListener('keydown', function(e) { if (e.key === 'Escape') chiudiAltro(); });
document.addEventListener('DOMContentLoaded', function() {
  var reg = document.getElementById('navRegistry');
  if (!reg) return;
  new MutationObserver(function(){ renderNav(); renderWho(); })
    .observe(reg, { subtree:true, childList:true, characterData:true, attributes:true, attributeFilter:['style','class'] });
  renderNav();
});

// Compatibilità con le chiamate storiche (prima c'era la sidebar)
function toggleSidebar() { toggleAltro(); }
function closeSidebar() { chiudiAltro(); }

function navTo(panel, title, btn) {
  showPanel(panel, null);
  closeSidebar();
}

function avviaDashboard() {
  document.getElementById('loginScreen').style.display = 'none';
  document.getElementById('app').style.display = 'flex';
  mostraWelcome(currentUser);

  const p        = currentUser.permessi || {};
  const isMaster = currentUser.tipo_accesso === 'master';
  const isVol    = currentUser.tipo_accesso === 'volontario';
  isMasterUser   = isMaster;
  window.isVolUser = isVol;

  // Topbar
  document.getElementById('homeWelcome').textContent = currentUser.nome;
  document.getElementById('homeUnit').textContent    = currentUser.ruolo;

  // Sidebar voci visibilita (vedi hasPerm() a livello di modulo)
  var showSi  = function(id) { var el=document.getElementById(id); if(el) el.style.display='flex'; };

  if (isVol) {
    // Reset esplicito di TUTTE le voci sidebar (per evitare residui)
    var allSidebarIds = [
      'siVolontari','siInterventi','siMezzi','siTlc','siDb',
      'siRichieste','siStatistiche','siImpostazioni','siAccessi',
      'siGalleria','siEditorPdf','siSegnalazioni','siPostazioni','siDotazioni','siPianiCarico',
      'siVisite','siFormazione','siConvocazioni','siEventi','siSci','siGestioneAccessi'
    ];
    allSidebarIds.forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });

    // Mostra solo le voci per volontari
    showSi('siSchedaPersonale');
    showSi('siGalleria');
    showSi('siSegnalazioni');
  } else {
    var spers = document.getElementById('siSchedaPersonale');
    if (spers) spers.style.display = 'none';

    // Documenti e visite ora stanno nella scheda: chi aveva solo quelle pagine entra da Volontari
    if (hasPerm('volontari') || hasPerm('documenti') || hasPerm('visite')) showSi('siVolontari');
    if (canModificaVolontari()) {
      var btnNuovo = document.getElementById('btnNuovoVolontario');
      if (btnNuovo) btnNuovo.style.display = '';
    }
    if (hasPerm('visite')) document.getElementById('btnExportVisite').hidden = false;
    if (hasPerm('visite'))       showSi('siVisite');
    if (hasPerm('formazione'))   showSi('siFormazione');
    if (hasPerm('interventi'))   showSi('siInterventi');
    if (hasPerm('postazioni'))   showSi('siPostazioni');
    if (hasPerm('dotazioni'))    showSi('siDotazioni');
    if (hasPerm('pianicarico'))  showSi('siPianiCarico');
    if (hasPerm('mezzi'))        showSi('siMezzi');
    if (hasPerm('tlc'))          showSi('siTlc');
    if (hasPerm('galleria'))     showSi('siGalleria');
    if (hasPerm('editor_pdf'))   showSi('siEditorPdf');
    if (hasPerm('convocazioni')) showSi('siConvocazioni');
    if (hasPerm('eventi'))       showSi('siEventi');
    if (hasPerm('statistiche'))  showSi('siStatistiche');
    if (hasPerm('db'))           showSi('siDb');
    if (hasPerm('accessi'))      showSi('siAccessi');
    if (isMaster)                showSi('siGestioneAccessi');
    // Le segnalazioni dei volontari e tutto il bot Telegram, per lo staff, stanno in S.C.I. (sci.js)
    if (hasPerm('sci') || hasPerm('eventi') || hasPerm('gestione_segnalazioni')) showSi('siSci');
    if (hasPerm('richieste'))    showSi('siRichieste');
    if (hasPerm('impostazioni')) showSi('siImpostazioni');
  }
  // Nome utente in sidebar
  var su = document.getElementById('sidebarUser');
  if (su) su.textContent = currentUser.nome + ' | ' + currentUser.ruolo;

  // Badge richieste (solo per non-volontari)
  if (!isVol && hasPerm('richieste')) caricaBadgeRichieste();
  if (!isVol) sciAggiornaBadge();

  // Compleanno
  verificaCompleanni();

  // Home cards
  buildHomeCards(isMaster, p);

  renderNav();
  renderWho();
  if (typeof btPromemoria === 'function') btPromemoria();
}



function logout() {
  logAttivita('ha effettuato il logout');
  currentUser = null;
  auEsci();
  document.getElementById('loginScreen').style.display = 'flex';
  document.getElementById('app').style.display = 'none';
  isMasterUser = false;
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  document.getElementById('panelHome').classList.add('active');
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  const navHome = document.getElementById('navHome');
  if (navHome) navHome.classList.add('active');
}

// -- NAVIGAZIONE --
const PANEL_PERM = {
  volontari: ['volontari','documenti','visite'], visite: ['visite'], formazione: ['formazione'],
  interventi: ['interventi'], postazioni: ['postazioni'], dotazioni: ['dotazioni'],
  pianiCarico: ['pianicarico'], mezzi: ['mezzi'], tlc: ['tlc'], galleria: ['galleria'],
  editorPdf: ['editor_pdf'], convocazioni: ['convocazioni'], eventi: ['eventi'], sci: ['sci','eventi','gestione_segnalazioni'], statistiche: ['statistiche'],
  db: ['db'], accessi: ['accessi'], richieste: ['richieste'], impostazioni: ['impostazioni'],
  aggDati: ['aggiornamento_dati'], verificaPiattaforme: ['aggiornamento_dati'], schedapers: ['scheda_personale'],
};
function puoAprirePannello(name) {
  if (name === 'gestioneAccessi') return !!currentUser && currentUser.tipo_accesso === 'master';
  return !PANEL_PERM[name] || PANEL_PERM[name].some(hasPerm);
}

function showPanel(name, btn) {
  if (!puoAprirePannello(name)) name = 'home';
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  const panel = document.getElementById('panel' + name.charAt(0).toUpperCase() + name.slice(1));
  if (panel) panel.classList.add('active');
  // Aggiorna active sidebar
  document.querySelectorAll('.sidebar-item').forEach(b => b.classList.remove('active'));
  var siId = name === 'schedapers' ? 'siSchedaPersonale' : 'si' + name.charAt(0).toUpperCase() + name.slice(1);
  var si = document.getElementById(siId);
  if (si) si.classList.add('active');
  else { var siH = document.getElementById('siHome'); if(siH) siH.classList.add('active'); }
  if (name === 'home') caricaAllerta();
  if (name === 'richieste') caricaRichieste();
  if (name === 'volontari') caricaVolontari();
  if (name === 'visite') caricaVisite();
  if (name === 'formazione') caricaFormazione();
  if (name === 'interventi') caricaInterventi();
  if (name === 'postazioni') caricaPostazioni();
  if (name === 'dotazioni') caricaDotazioni();
  if (name === 'pianiCarico') caricaPianiCarico();
  if (name === 'impostazioni') caricaCategorieDotazioni();
  if (name === 'db') caricaDb();
  if (name === 'mezzi') caricaMezzi();
  if (name === 'tlc') caricaTlc();
  if (name === 'galleria') caricaGalleria();
  if (name === 'editorPdf') caricaEditorPdf();
  if (name === 'convocazioni') caricaConvocazioni();
  if (name === 'eventi') caricaEventi();
  if (name === 'sci') caricaSci();
  if (name === 'schedapers') caricaSchedaPersonale();
  if (name === 'segnalazioni') caricaSegnalazioni();
  if (name === 'accessi') caricaAccessi();
  if (name === 'gestioneAccessi') caricaGestioneAccessi();
  if (name === 'statistiche') {
    if (typeof Chart === 'undefined') {
      var s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js';
      s.onload = initStatistiche;
      document.head.appendChild(s);
    } else {
      initStatistiche();
    }
  }
}

function toggleMore(){} function closeMore(){}

// -- HOME CARDS --
function buildHomeCards(isMaster, p) {
  caricaAllerta();
  caricaHomeDashboard();
}

async function caricaHomeDashboard() {
  const grid = document.getElementById('homeGrid');
  if (!grid) return;
  grid.innerHTML = '<p class="note">Caricamento…</p>';

  try {
    const oggi = new Date();
    const mm   = String(oggi.getMonth() + 1).padStart(2,'0');

    // Carica compleanni del mese e ultimi interventi in parallelo
    const [volRes, intRes] = await Promise.all([
      sbFetch(SUPA_URL + '/rest/v1/volontari_pubblici?select=id,cognome,nome,data_nascita,squadra,foto_url,stato&or=(stato.is.null,stato.neq.DIMESSO)&order=data_nascita', { headers: H }),
      window.isVolUser ? null : sbFetch(SUPA_URL + '/rest/v1/interventi_recenti?select=id,evento,data,data_fine,tipo_attivita,luogo,n_volontari,n_ore,stato_calcolato&stato_calcolato=eq.SVOLTO&order=data.desc&limit=5', { headers: H })
    ]);
    const volontari  = await volRes.json();
    const interventi = intRes ? await intRes.json() : [];
    const vedeInterventi = hasPerm('interventi');

    // Filtra compleanni del mese
    const bdayMonth = (volontari || []).filter(v => {
      if (!v.data_nascita) return false;
      return v.data_nascita.slice(5,7) === mm;
    }).sort((a,b) => {
      return parseInt(a.data_nascita.slice(8,10)) - parseInt(b.data_nascita.slice(8,10));
    });

    await sbFirmaRighe(bdayMonth, 'foto_url');

    const mesiIt = ['','Gennaio','Febbraio','Marzo','Aprile','Maggio','Giugno','Luglio','Agosto','Settembre','Ottobre','Novembre','Dicembre'];
    const mesiBr = ['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set','Ott','Nov','Dic'];
    const dtTile = function(iso) {
      return '<div class="dt"><b>' + iso.slice(8,10) + '</b><span>' + mesiBr[parseInt(iso.slice(5,7)) - 1] + '</span></div>';
    };
    let left = '', right = '';

    // -- ULTIMI INTERVENTI -- (skip per volontari; senza permesso si leggono ma non si aprono)
    if (intRes && intRes.ok) {
      left += '<div class="card"><div class="phead mb6"><h2>Ultimi interventi</h2>'
        + (vedeInterventi ? '<button class="btn sm" onclick="navTo(&quot;interventi&quot;,&quot;Interventi&quot;,document.getElementById(&quot;siInterventi&quot;))">Vedi tutti →</button>' : '') + '</div>';
      if (!interventi || !interventi.length) {
        left += '<p class="note">Nessun intervento registrato.</p>';
      } else {
        interventi.forEach(i => {
          var onclickInt = 'navTo(&quot;interventi&quot;,&quot;Interventi&quot;,document.getElementById(&quot;siInterventi&quot;));apriDettaglioIntervento(' + i.id + ')';
          left += (vedeInterventi ? '<div class="lr clk" onclick="' + onclickInt + '">' : '<div class="lr">')
            + (i.data ? dtTile(i.data) : '<div class="dt"><b>—</b></div>')
            + '<div class="mid"><b>' + (i.evento||'—') + '</b><span class="sub">' + (i.tipo_attivita || '') + '</span></div>'
            + '<div class="end">' + (i.n_volontari||0) + ' vol' + (i.n_ore ? ' · ' + i.n_ore + ' h' : '') + '</div>'
            + '</div>';
        });
      }
      left += '</div>';
    }

    // -- DA SISTEMARE (volontari) --
    try { right += await svCardDashboard(); } catch(e) {}

    // -- REVISIONI IN SCADENZA -- (skip per volontari)
    if (!window.isVolUser && hasPerm('mezzi')) try {
      var mezziRes  = await sbFetch(SUPA_URL + '/rest/v1/mezzi?select=id,automezzo,targa,revisione,stato&order=revisione', { headers: H });
      var mezziAll  = await mezziRes.json();
      var oggi2     = new Date();
      var mmPad     = String(oggi2.getMonth()+1).padStart(2,'0');
      var yyStr     = String(oggi2.getFullYear());
      var revMese   = (mezziAll||[]).filter(function(m){
        if (!m.revisione) return false;
        return m.revisione.slice(0,7) === yyStr + '-' + mmPad;
      });
      var revScadute = (mezziAll||[]).filter(function(m){
        if (!m.revisione) return false;
        return new Date(m.revisione) < oggi2;
      });
      // Mostro revisioni scadute + del mese
      var revDaMostrare = [];
      revScadute.forEach(function(m){ if (!revDaMostrare.find(function(x){return x.id===m.id;})) revDaMostrare.push(m); });
      revMese.forEach(function(m){ if (!revDaMostrare.find(function(x){return x.id===m.id;})) revDaMostrare.push(m); });

      if (revDaMostrare.length) {
        right += '<div class="card"><h2>Revisioni in scadenza</h2>';
        revDaMostrare.forEach(function(m) {
          var d       = new Date(m.revisione);
          var scaduta = d < oggi2;
          right += '<button class="todo" onclick="navTo(&quot;mezzi&quot;,&quot;Mezzi&quot;,document.getElementById(&quot;siMezzi&quot;))">'
            + '<span class="dot ' + (scaduta ? 'red' : 'yellow') + '"></span>'
            + '<span class="grow"><b>' + m.automezzo + '</b> <span class="targa">' + (m.targa||'—') + '</span>'
            + '<span class="sub">' + (scaduta ? 'Scaduta il ' : 'Scade il ') + d.toLocaleDateString('it-IT') + '</span></span>'
            + '<span class="go">→</span></button>';
        });
        right += '</div>';
      }
    } catch(e) {}

    // -- COMPLEANNI DEL MESE --
    if (volRes.ok) right += '<div class="card"><h2>Compleanni di ' + mesiIt[oggi.getMonth()+1] + '</h2>';
    if (!volRes.ok) {
      // sezione nascosta
    } else if (!bdayMonth.length) {
      right += '<p class="note">Nessun compleanno questo mese.</p>';
    } else {
      const oggiMd = mm + '-' + String(oggi.getDate()).padStart(2,'0');
      bdayMonth.forEach(v => {
        const isOggi   = v.data_nascita.slice(5,10) === oggiMd;
        const eta      = oggi.getFullYear() - parseInt(v.data_nascita.slice(0,4));
        right += '<div class="lr">'
          + sbAvatar(v, 'av s40')
          + '<div class="mid"><b>' + v.cognome + ' ' + v.nome + '</b><span class="sub">' + v.data_nascita.slice(8,10) + ' ' + mesiIt[oggi.getMonth()+1] + ' · ' + eta + ' anni</span></div>'
          + (isOggi ? '<span class="pill p-yellow">Oggi</span>' : '')
          + '</div>';
      });
    }
    if (volRes.ok) right += '</div>';

    if (!left && !right) { grid.innerHTML = '<div class="empty">Non disponibile.</div>'; return; }
    grid.innerHTML = left
      ? '<div class="cols home-cols">' + left + '<div class="stack">' + right + '</div></div>'
      : '<div class="stack">' + right + '</div>';

  } catch(e) {
    grid.innerHTML = '<div class="empty">Non disponibile.</div>';
  }
}

