// -- COMPLEANNI --
async function verificaCompleanni() {
  try {
    const oggi = new Date();
    const mm   = String(oggi.getMonth() + 1).padStart(2, '0');
    const dd   = String(oggi.getDate()).padStart(2, '0');
    const res  = await sbFetch(SUPA_URL + '/rest/v1/volontari_pubblici?select=nome,cognome,data_nascita,stato&or=(stato.is.null,stato.neq.DIMESSO)', { headers: H });
    const utenti = await res.json();
    const compleanni = (utenti || []).filter(u => {
      if (!u.data_nascita) return false;
      const parts = u.data_nascita.split('-');
      return parts[1] === mm && parts[2] === dd;
    });
    if (compleanni.length > 0) {
      const nomi   = compleanni.map(u => (u.cognome + ' ' + u.nome).trim()).join(', ');
      const banner = document.getElementById('bdayBanner');
      const text   = document.getElementById('bdayText');
      text.innerHTML = 'Oggi è il compleanno di <strong>' + nomi + '</strong> — ricordati di fargli gli auguri!';
      banner.style.display = 'flex';
    }
  } catch(e) {}
}

// -- LOG ATTIVITÀ --
async function logAttivita(azione) {
  if (!currentUser) return;
  try {
    await sbFetch(SUPA_URL + '/rest/v1/log_attivita', {
      method: 'POST',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ utente_nome: currentUser.nome, azione }),
      silenzioso: true
    });
  } catch(e) {}
}

// -- RICHIESTE --
async function caricaBadgeRichieste() {
  try {
    const res  = await sbFetch(SUPA_URL + '/rest/v1/richieste_adesione?letta=eq.false&select=id', { headers: H });
    const data = await res.json();
    const badge = document.getElementById('siBadgeRichieste');
    if (data.length > 0) { badge.textContent = data.length; badge.classList.add('show'); }
    else badge.classList.remove('show');
  } catch(e) {}
}

async function caricaRichieste() {
  const list = document.getElementById('richiesteList');
  list.innerHTML = '<div class="loading-msg">Caricamento…</div>';
  try {
    const res       = await sbFetch(SUPA_URL + '/rest/v1/richieste_adesione?select=*&order=created_at.desc', { headers: H });
    sbOk(res);
    const richieste = await res.json();
    const nonLette  = richieste.filter(r => !r.letta).length;
    const badge     = document.getElementById('siBadgeRichieste');
    if (nonLette > 0) { badge.textContent = nonLette; badge.classList.add('show'); }
    else badge.classList.remove('show');
    if (!richieste.length) { list.innerHTML = '<div class="empty">Nessuna richiesta.</div>'; return; }
    list.innerHTML = '';
    richieste.forEach(r => {
      const data = new Date(r.created_at).toLocaleDateString('it-IT', { day:'2-digit', month:'2-digit', year:'numeric' });
      const div  = document.createElement('div');
      div.className = 'card ric-card' + (r.letta ? ' letta' : '');
      const tag   = r.letta ? '<span class="pill p-grey">Letta</span>' : '<span class="pill p-yellow">Nuova</span>';
      const socio = r.socio_ana ? '<div>Socio ANA: ' + r.socio_ana + (r.gruppo_ana ? ' — ' + r.gruppo_ana : '') + '</div>' : '';
      const msg   = r.messaggio ? '<div class="ric-msg">"' + r.messaggio + '"</div>' : '';
      const tel   = r.telefono  ? ' · ' + r.telefono : '';
      const ini   = (r.nome || '?').split(' ').map(x => x[0] || '').join('').slice(0,2).toUpperCase();
      const btnL  = r.letta ? '' : '<button class="btn sm pri" onclick="segnaLetta(\'' + r.id + '\')">Segna letta</button>';
      div.innerHTML = '<div class="vc"><span class="av">' + ini + '</span><div class="mid"><b>' + r.nome + '</b><span class="sub">' + data + '</span></div>' + tag + '</div>'
        + '<div class="ric-body"><div>' + r.email + tel + '</div>' + socio + msg + '</div>'
        + '<div class="em-azioni">' + btnL + '<button class="btn sm danger" onclick="eliminaRichiesta(\'' + r.id + '\')">Elimina</button></div>';
      list.appendChild(div);
    });
  } catch(e) { list.innerHTML = '<div class="empty">Non disponibile.</div>'; }
}

async function segnaLetta(id) {
  await sbFetch(SUPA_URL + '/rest/v1/richieste_adesione?id=eq.' + id, { method:'PATCH', headers:HJ, body:JSON.stringify({ letta:true }) });
  await logAttivita('ha segnato una richiesta come letta');
  caricaRichieste();
}

async function eliminaRichiesta(id) {
  if (!confirm('Eliminare questa richiesta?')) return;
  await sbFetch(SUPA_URL + '/rest/v1/richieste_adesione?id=eq.' + id, { method:'DELETE', headers:H });
  await logAttivita('ha eliminato una richiesta adesione');
  caricaRichieste();
}

// -- IMPOSTAZIONI --
const GUIDA_URL = "https://pcanacasale.com/guida/";
let guidaCopiaTimer = null;

async function caricaImpostazioni() {
  document.getElementById('guidaImpoBox').hidden = currentUser.tipo_accesso !== 'master';
  document.getElementById('guidaApri').href = GUIDA_URL;
  document.getElementById('btImpoBox').hidden = !(hasPerm('eventi') || hasPerm('sci'));
  renderSchemaList();
  evCaricaListe();
}

function guidaCopiaFallback() {
  const campo = document.createElement('textarea');
  campo.value = GUIDA_URL;
  campo.setAttribute('readonly', '');
  campo.style.cssText = 'position:fixed;opacity:0';
  document.body.appendChild(campo);
  campo.select();
  let fatto = false;
  try { fatto = document.execCommand('copy'); } catch(e) { /* resta false */ }
  campo.remove();
  return fatto;
}

async function guidaCopiaLink() {
  let fatto = false;
  try { await navigator.clipboard.writeText(GUIDA_URL); fatto = true; }
  catch(e) { fatto = guidaCopiaFallback(); }
  if (!fatto) { sbAvviso('Copia non riuscita. Il link è ' + GUIDA_URL); return; }
  const btn = document.getElementById('guidaCopia');
  btn.textContent = 'Copiato';
  clearTimeout(guidaCopiaTimer);
  guidaCopiaTimer = setTimeout(() => { btn.textContent = 'Copia link'; }, 2000);
}

// -- VOLONTARI --
let volontariData = [];
let volCorrenteId = null;

// Avatar come nel riferimento: giallo chiaro o azzurro, testo blu
const AVATAR_COLORS = [
  ['var(--yellow-soft)','var(--fg)'], ['var(--soft)','var(--fg)']
];

function avatarColor(str) {
  let h = 0; for (let c of (str||'')) h = (h*31 + c.charCodeAt(0)) & 0xffffffff;
  return AVATAR_COLORS[Math.abs(h) % AVATAR_COLORS.length];
}

async function caricaVolontari() {
  const list = document.getElementById('volList');
  if (!list) return;
  list.innerHTML = '<p class="note">Caricamento…</p>';
  if (!visteCache.length) caricaViste();
  try {
    const res  = await sbFetch(SUPA_URL + '/rest/v1/volontari?select=id,cognome,nome,squadra,tipo_volontario,mansione,specializzazione,telefono,quattro_ore,dodici_ore,esonero_12_ore,dae,pronto_impiego,stato_visita,attivo,stato,foto_url,codice_fiscale,data_visita,cdc_1_step,cdc_2_step&order=cognome', { headers: H });
    sbOk(res);
    volontariData = await res.json();
    await sbFirmaRighe(volontariData, 'foto_url');
    document.getElementById('volTot').textContent = volontariData.length;
    await svCaricaProblemi(volontariData);
    svRenderFiltri();
    if (svFiltro) filtraVolontari(); else renderVolontari(volontariData);
  } catch(e) { list.innerHTML = '<div class="empty full-row">Non disponibile.</div>'; }
}

function renderVolontari(data) {
  const list = document.getElementById('volList');
  if (!list) return;
  document.getElementById('volMostrati').textContent = data.length;
  if (!data.length) { list.innerHTML = '<div class="empty full-row">Nessun volontario trovato.</div>'; return; }

  // Separa attivi+sospesi da dimessi
  const attiviSospesi = data.filter(v => (v.stato || 'ATTIVO') !== 'DIMESSO');
  const dimessi       = data.filter(v => v.stato === 'DIMESSO');

  list.innerHTML = '';
  attiviSospesi.forEach(v => list.appendChild(_renderVolCard(v)));

  if (dimessi.length) {
    const sep = document.createElement('div');
    sep.className = 'grp';
    sep.textContent = 'Dimessi (' + dimessi.length + ')';
    list.appendChild(sep);
    dimessi.forEach(v => list.appendChild(_renderVolCard(v)));
  }
}

// Pillole di stato come nel riferimento: Attivo blu chiaro, Sospeso/Dimesso grigio
const VOL_STATO_PILL = { ATTIVO:['Attivo','p-blue'], SOSPESO:['Sospeso','p-grey'], DIMESSO:['Dimesso','p-grey'] };
function _volAvatar(v) { return sbAvatar(v, 'av'); }
function _volCardHtml(v, statoHtml, tags) {
  return '<div class="vc">' + _volAvatar(v)
    + '<div class="mid"><b>' + v.cognome + ' ' + v.nome + '</b><span class="sub">' + (v.tipo_volontario||'—') + (v.mansione ? ' · ' + v.mansione : '') + '</span></div>'
    + statoHtml + '</div>'
    + '<div class="cfoot"><span class="vol-tags">' + (tags.length ? tags.join('') : '<span>' + (v.squadra || 'Nessuna squadra') + '</span>') + '</span>'
    + '<b class="go">Apri scheda →</b></div>';
}

function _renderVolCard(v) {
  const stato = v.stato || 'ATTIVO';
  const card = document.createElement('div');
  card.className = 'card clk vcard' + (stato === 'DIMESSO' ? ' off' : '');
  card.onclick = (e) => { if (!e.target.closest('.vol-stato-sel')) apriDettaglio(v.id); };

  const badges = [];
  if (v.squadra) badges.push('<span class="pill p-sand">' + v.squadra + '</span>');
  if (v.dae) badges.push('<span class="pill p-blue">DAE</span>');
  if (v.pronto_impiego) badges.push('<span class="pill p-blue">PI</span>');

  // Dropdown stato inline (se può modificare) o pillola readonly
  const statoCls = 'pill ' + (VOL_STATO_PILL[stato] || VOL_STATO_PILL.ATTIVO)[1];
  let statoSel;
  if (canModificaVolontari()) {
    statoSel = '<select class="vol-stato-sel ' + statoCls + '" onclick="event.stopPropagation()" onchange="cambiaStatoVolontario(' + v.id + ', this.value, this)" aria-label="Stato">'
      + '<option value="ATTIVO"' + (stato==='ATTIVO'?' selected':'') + '>Attivo</option>'
      + '<option value="SOSPESO"' + (stato==='SOSPESO'?' selected':'') + '>Sospeso</option>'
      + '<option value="DIMESSO"' + (stato==='DIMESSO'?' selected':'') + '>Dimesso</option>'
      + '</select>';
  } else {
    statoSel = '<span class="' + statoCls + '">' + (VOL_STATO_PILL[stato] || [stato])[0] + '</span>';
  }

  card.innerHTML = _volCardHtml(v, statoSel, badges);
  return card;
}

async function cambiaStatoVolontario(volId, nuovoStato, selEl) {
  if (!canModificaVolontari()) {
    alert('Permessi insufficienti per modificare lo stato.');
    return;
  }
  // Trova volontario in cache
  const v = volontariData.find(x => x.id === volId);
  if (!v) return;
  const vecchio = v.stato || 'ATTIVO';
  if (vecchio === nuovoStato) return;

  // Conferma per DIMESSO
  if (nuovoStato === 'DIMESSO') {
    if (!confirm('Spostare ' + v.cognome + ' ' + v.nome + ' tra i DIMESSI?')) {
      selEl.value = vecchio;
      return;
    }
  }

  selEl.disabled = true;
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + volId, {
      method: 'PATCH',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ stato: nuovoStato, attivo: nuovoStato !== 'DIMESSO' })
    });
    if (!res.ok) throw new Error('errore');
    v.stato = nuovoStato;
    v.attivo = nuovoStato !== 'DIMESSO';
    await logAttivita('ha cambiato stato di ' + v.cognome + ' ' + v.nome + ' a ' + nuovoStato);
    renderVolontari(volontariData);
  } catch(e) {
    selEl.value = vecchio;
    alert('Errore salvataggio.');
  }
  selEl.disabled = false;
}

function filtraVolontari() {
  const q       = (document.getElementById('volSearch').value || '').toLowerCase().trim();
  const squadra = document.getElementById('filtroSquadra').value;
  const tipo    = document.getElementById('filtroTipo').value;
  const mansione = document.getElementById('filtroMansione').value;
  const attivo  = document.getElementById('filtroAttivo').value;
  const visita  = document.getElementById('filtroVisita').value;
  const filtered = volontariData.filter(v => {
    const nome = (v.cognome + ' ' + v.nome + ' ' + (v.squadra||'') + ' ' + (v.codice_fiscale||'')).toLowerCase();
    if (q && !nome.includes(q)) return false;
    if (squadra && v.squadra !== squadra) return false;
    if (tipo && v.tipo_volontario !== tipo) return false;
    if (mansione && v.mansione !== mansione) return false;
    if (attivo === 'true' && !v.attivo) return false;
    if (attivo === 'false' && v.attivo) return false;
    if (visita && (visitaStatoNorm(v) || 'VUOTO') !== visita) return false;
    return svPassaFiltro(v);
  });
  renderVolontari(filtered);
}

