    setVal('fProfessione', v.professione); setVal('fIndirizzo', v.indirizzo);
    setVal('fCap', v.cap); setVal('fCitta', v.citta);
    setVal('fSquadra', v.squadra); setVal('fTipo', v.tipo_volontario);
