    + '.dl{border:none;border-top:0.8px solid #b8dfc9;margin:4mm 0}'
    + '.titolo{text-align:center;font-size:20pt;font-weight:700;text-decoration:underline;letter-spacing:.5px;margin:2mm 0}'
