    + '.frow{display:flex;justify-content:space-between;align-items:flex-end;margin-top:auto;padding-top:8mm;font-size:10.5pt}'
    + '.flabel{font-style:italic;text-align:center;margin-bottom:1mm}'
    + '.fimg{width:45mm;height:auto;display:block;margin:0 auto}'
    + '.fline{border-top:1px solid #333;width:55mm;margin:2mm auto 0}'
