// -- DOCUMENTI --
let docUploadVolId = null;
let docUploadFile  = null;

const DOC_TIPO_LABEL = {
  'FOTO':'📷 Foto profilo',
  'IDENTITA':"🪪 Documento d'identità",
  '4_ORE':'📜 Attestato 4 Ore', '12_ORE':'📜 Attestato 12 Ore',
  'CAPOSQ':'📜 Caposquadra', 'DAE':'📜 DAE',
  'CDC_1':'📜 CDC 1° Step', 'CDC_2':'📜 CDC 2° Step',
  'EMERCOM':'📜 EMERCOM', 'ATTESTATO':'📜 Attestato intervento',
  'VISITA':'🩺 Visita medica', 'ALTRO':'📄 Altro'
};

// Tipi che sono attestati (bucket 'attestati')
const DOC_TIPI_ATTESTATO = ['4_ORE','12_ORE','CAPOSQ','DAE','CDC_1','CDC_2','EMERCOM','ATTESTATO'];

function bucketPerDocTipo(tipo) {
  if (tipo === 'FOTO') return 'foto-volontari';
  if (DOC_TIPI_ATTESTATO.indexOf(tipo) >= 0) return 'attestati';
  return 'documenti';
}

function apriUploadDoc(volId, tipo) {
  docUploadVolId = volId;
  docUploadFile  = null;
  const v = sv && sv.id === volId ? sv.v : null;
  // Con l'archivio PIA la foto passa dall'editor (196×236, JPG, nome COGNOME_NOME_PIA.jpg)
  document.querySelector('#docTipo option[value="FOTO"]').disabled = !!sv && !!sv.agg;
  document.getElementById('docTipo').value = tipo || 'IDENTITA';
  document.getElementById('docUploadTitle').textContent = 'Carica documento — ' + (v ? v.cognome + ' ' + v.nome : '');
  document.getElementById('docUploadErr').style.display = 'none';
  document.getElementById('docDropText').innerHTML = 'PDF, JPG o PNG — max 10MB';
  document.getElementById('docNome').value = '';
  document.getElementById('docProgress').style.display = 'none';
  document.getElementById('docProgressBar').style.width = '0%';
  document.getElementById('docFileInput').value = '';
  document.getElementById('docUploadOverlay').classList.add('open');
}

function chiudiUploadDoc() {
  document.getElementById('docUploadOverlay').classList.remove('open');
  docUploadVolId = null;
  docUploadFile  = null;
}

function docFileSelected(input) {
  const file = input.files[0];
  if (!file) return;
  if (file.size > 10 * 1024 * 1024) {
    document.getElementById('docUploadErr').textContent = 'File troppo grande (max 10MB).';
    document.getElementById('docUploadErr').style.display = 'block';
    return;
  }
  docUploadFile = file;
  var txt = document.getElementById('docDropText');
  if (txt) txt.textContent = '✓ ' + file.name + ' (' + (file.size/1024).toFixed(0) + ' KB)';
}

async function eseguiUploadDoc() {
  if (!docUploadFile || !docUploadVolId) {
    document.getElementById('docUploadErr').textContent = 'Seleziona un file.';
    document.getElementById('docUploadErr').style.display = 'block';
    return;
  }
  const tipo    = document.getElementById('docTipo').value;
  const nomeDoc = document.getElementById('docNome').value.trim() || docUploadFile.name;
  const bucket  = bucketPerDocTipo(tipo);
  const path    = docUploadVolId + '/' + tipo + '_' + Date.now() + '_' + docUploadFile.name.replace(/[^a-zA-Z0-9._-]/g,'_');
  const errEl   = document.getElementById('docUploadErr');
  const btn     = document.getElementById('docUploadBtn');
  const progress = document.getElementById('docProgress');
  const bar      = document.getElementById('docProgressBar');

  errEl.style.display = 'none';
  btn.disabled = true; btn.textContent = 'caricamento...';
  progress.style.display = 'block';

  try {
    // Upload su Supabase Storage
    bar.style.width = '30%';
    const uploadRes = await sbFetch(SUPA_URL + '/storage/v1/object/' + bucket + '/' + path,
      { method: 'POST', headers: { 'apikey': SUPA_KEY, 'Content-Type': docUploadFile.type }, body: docUploadFile }
    );
    bar.style.width = '70%';
    if (!uploadRes.ok) throw new Error('Errore upload storage');

    // URL pubblico
    const url = sbPercorso(bucket, path);

    // Salva record in documenti
    const docRes = await sbFetch(SUPA_URL + '/rest/v1/documenti', {
      method: 'POST',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ volontario_id: docUploadVolId, tipo, nome_file: nomeDoc, url })
    });
    bar.style.width = '100%';
    if (!docRes.ok) throw new Error('Errore salvataggio record');

    // Se è foto, aggiorna avatar volontario
    if (tipo === 'FOTO') {
      await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + docUploadVolId, {
        method: 'PATCH', headers: HJ, body: JSON.stringify({ foto_url: url })
      });
    }

    await logAttivita('ha caricato documento: ' + nomeDoc + ' per volontario ' + docUploadVolId);
    chiudiUploadDoc();
    await svRicaricaDocumenti();
  } catch(e) {
    errEl.textContent = 'Errore: ' + e.message;
    errEl.style.display = 'block';
  }
  btn.disabled = false; btn.textContent = 'Carica';
}

async function eliminaDoc(docId, volId) {
  if (!confirm('Eliminare questo documento?')) return;

  // Recupera info del documento per sapere tipo e path
  let doc = null;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/documenti?id=eq.' + docId + '&select=tipo,url', { headers: H });
    const arr = await r.json();
    doc = arr[0];
  } catch(e) {}

  // Elimina file dal bucket Storage
  if (doc && doc.url) {
    try {
      await sbEliminaFile(doc.url);
    } catch(e) {}
  }

  // Elimina record dalla tabella documenti
  await sbFetch(SUPA_URL + '/rest/v1/documenti?id=eq.' + docId, { method: 'DELETE', headers: H });

  // Se era una FOTO, azzera foto_url sul volontario
  if (doc && doc.tipo === 'FOTO' && volId) {
    await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + volId, {
      method: 'PATCH',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ foto_url: null })
    });
  }

  await logAttivita('ha eliminato un documento');
  await svRicaricaDocumenti();
}

