// -- VERIFICA CF (pagina DB Avanzato) --
async function eseguiVerificaCF() {
  const box = document.getElementById('verCFRisultati');
  if (!box) return;
  box.style.display = 'block';
  box.innerHTML = '<div class="card vcf-card"><p class="note m0">Verifica in corso…</p></div>';
  let vols;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/volontari?select=id,cognome,nome,codice_fiscale,data_nascita,luogo_nascita&stato=neq.DIMESSO&order=cognome,nome', { headers: H });
    sbOk(r);
    vols = await r.json();
  } catch(e) {
    box.innerHTML = '<div class="card vcf-card"><p class="bad m0">Non disponibile.</p></div>';
    return;
  }

  const errori = [], info = [];
  let ok = 0;
  vols.forEach(v => {
    const nomeC = (v.cognome||'') + ' ' + (v.nome||'');
    if (!v.codice_fiscale) { errori.push({ v: nomeC, msg: 'CF mancante' }); return; }
    const chk = validaCodiceFiscale(v.codice_fiscale);
    if (!chk.ok) { errori.push({ v: nomeC, msg: 'CF non valido: ' + chk.msg }); return; }
    if (!v.data_nascita) {
      const dec = decodificaCF(chk.cf);
      errori.push({ v: nomeC, msg: 'Data di nascita mancante nel DB (il CF indica ' + (dec.dataISO ? dec.dataISO.split('-').reverse().join('/') : '?') + ')' });
    }
    const disc = verificaCoerenzaCF(chk.cf, v.data_nascita, v.luogo_nascita);
    if (v.data_nascita && !v.luogo_nascita) info.push({ v: nomeC, msg: 'Luogo di nascita mancante nel DB' });
    let haErr = false;
    disc.forEach(x => {
      if (x.tipo === 'errore') { errori.push({ v: nomeC, msg: x.msg }); haErr = true; }
      else info.push({ v: nomeC, msg: x.msg });
    });
    if (!haErr && v.data_nascita) ok++;
  });

  const rigaTab = arr => {
    let t = '<div class="card tbl acc-log"><div class="irow ihead"><span>Volontario</span><span>Dettaglio</span><span></span></div>';
    arr.forEach(p => {
      t += '<div class="irow"><b class="nowrap">' + p.v + '</b><span>' + p.msg + '</span><span></span></div>';
    });
    return t + '</div>';
  };

  let out = '<div class="card vcf-card">'
    + '<div class="vcf-head">'
    + '<span><strong>' + vols.length + '</strong> volontari verificati — '
    + '<span class="pill p-blue">' + ok + ' coerenti</span> '
    + '<span class="pill p-red">' + errori.length + ' discrepanze</span>'
    + (info.length ? ' <span class="pill p-grey">' + info.length + ' avvisi</span>' : '') + '</span>'
    + '<button class="btn sm" onclick="document.getElementById(\'verCFRisultati\').style.display=\'none\'">Chiudi</button>'
    + '</div>';
  if (errori.length) out += rigaTab(errori);
  if (info.length) out += '<details class="vcf-avvisi"><summary>Avvisi non bloccanti (' + info.length + ')</summary>' + rigaTab(info) + '</details>';
  if (!errori.length && !info.length) out += '<p class="note">Nessuna discrepanza trovata.</p>';
  out += '</div>';
  box.innerHTML = out;
}

// -- GESTIONE POSTAZIONI --
let pstIntervento = null;      // record intervento selezionato
let pstInterventiOpts = [];    // lista per la select
let pstPostazioni = [];        // postazioni dell'intervento corrente, ciascuna con .volontari[]
let pstVolontariIntervento = []; // volontari collegati all'intervento corrente (unica fonte per assegnazioni e import massivo)
let pstTargetPostazioneId = null;

function _pstLabelRadio(t) {
  return [t.marca, t.modello, t.selettiva].filter(Boolean).join(' ') || ('Radio #' + t.id);
}
function _pstLabelMezzo(m) {
  return [m.automezzo, m.targa].filter(Boolean).join(' — ') || ('Mezzo #' + m.id);
}

async function _pstCaricaRadioMezzoOpts() {
  if (!tlcData || !tlcData.length) {
    try { const r = await sbFetch(SUPA_URL + '/rest/v1/tlc?select=id,marca,modello,selettiva&order=marca', { headers: H }); tlcData = await r.json(); } catch(e) { tlcData = tlcData || []; }
  }
  if (!mezziData || !mezziData.length) {
    try { const r = await sbFetch(SUPA_URL + '/rest/v1/mezzi?select=id,automezzo,targa&order=automezzo', { headers: H }); mezziData = await r.json(); } catch(e) { mezziData = mezziData || []; }
  }
  const optsRadio = '<option value="">— radio (nessuna) —</option>' + tlcData.map(t => '<option value="' + t.id + '">' + _pstLabelRadio(t) + '</option>').join('');
  const optsMezzo = '<option value="">— mezzo (nessuno) —</option>' + mezziData.map(m => '<option value="' + m.id + '">' + _pstLabelMezzo(m) + '</option>').join('');
  ['pstFRadio','pstEFRadio'].forEach(id => { const el = document.getElementById(id); if (el) el.innerHTML = optsRadio; });
  ['pstFMezzo','pstEFMezzo'].forEach(id => { const el = document.getElementById(id); if (el) el.innerHTML = optsMezzo; });
}

async function caricaPostazioni() {
  const sel = document.getElementById('pstIntervento');
  if (!sel) return;
  const prevVal = sel.value;
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/interventi?select=id,evento,data,luogo,volontari_ids&usa_postazioni=eq.true&order=data.desc&limit=500', { headers: H });
    if (!res.ok) {
      sel.innerHTML = '<option value="">Non disponibile</option>';
      document.getElementById('pstBody').style.display = 'none';
      return;
    }
    pstInterventiOpts = await res.json();
  } catch(e) { pstInterventiOpts = []; }

  const empty = document.getElementById('pstEmpty');
  if (!pstInterventiOpts.length) {
    sel.innerHTML = '<option value="">— nessun intervento abilitato —</option>';
    if (empty) { empty.style.display = 'block'; empty.textContent = 'nessun intervento ha la gestione postazioni attiva. Abilitala dal form di modifica dell\'intervento (checkbox "📍 Gestione Postazioni").'; }
    document.getElementById('pstBody').style.display = 'none';
    return;
  }

  sel.innerHTML = '<option value="">— seleziona un intervento —</option>' + pstInterventiOpts.map(i => {
    const d = i.data ? new Date(i.data).toLocaleDateString('it-IT') : '—';
    return '<option value="' + i.id + '">' + (i.evento || 'senza nome') + ' — ' + d + (i.luogo ? ' (' + i.luogo + ')' : '') + '</option>';
  }).join('');

  await _pstCaricaRadioMezzoOpts();

  if (prevVal) { sel.value = prevVal; pstSelezionaIntervento(prevVal); }
}

async function pstSelezionaIntervento(interventoId) {
  const body  = document.getElementById('pstBody');
  const empty = document.getElementById('pstEmpty');
  if (!interventoId) {
    pstIntervento = null; pstPostazioni = []; pstVolontariIntervento = [];
    if (body) body.style.display = 'none';
    if (empty) { empty.style.display = 'block'; empty.textContent = 'seleziona un intervento per gestire le postazioni.'; }
    return;
  }
  pstIntervento = pstInterventiOpts.find(i => String(i.id) === String(interventoId)) || { id: interventoId };
  if (body) body.style.display = 'block';
  if (empty) empty.style.display = 'none';
  const searchEl = document.getElementById('pstSearch');
  if (searchEl) searchEl.value = '';
  pstMostraTab('elenco');
  await pstCaricaVolontariIntervento();
  await pstCaricaLista();
}

// Carica i volontari collegati all'intervento corrente (nuovo schema + fallback legacy)
async function pstCaricaVolontariIntervento() {
  pstVolontariIntervento = [];
  if (!pstIntervento) return;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/intervento_volontari?intervento_id=eq.' + pstIntervento.id + '&select=volontario_id,volontario:volontario_id(id,cognome,nome,squadra,telefono)', { headers: H });
    const rows = await r.json();
    if (Array.isArray(rows) && rows.length) {
      pstVolontariIntervento = rows.filter(x => x.volontario).map(x => ({ id: x.volontario.id, cognome: x.volontario.cognome, nome: x.volontario.nome, squadra: x.volontario.squadra, telefono: x.volontario.telefono }));
      return;
    }
  } catch(e) {}
  // Fallback legacy
  if (pstIntervento.volontari_ids && pstIntervento.volontari_ids.length) {
    try {
      const r = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=in.(' + pstIntervento.volontari_ids.join(',') + ')&select=id,cognome,nome,squadra,telefono', { headers: H });
      pstVolontariIntervento = await r.json();
    } catch(e) {}
  }
}

async function pstCaricaLista() {
  const list = document.getElementById('pstList');
  if (!list || !pstIntervento) return;
  list.innerHTML = '<div class="loading-msg">caricamento...</div>';
  try {
    const rP = await sbFetch(SUPA_URL + '/rest/v1/postazioni?select=*&intervento_id=eq.' + pstIntervento.id + '&order=ordine.asc', { headers: H });
    sbOk(rP);
    const postazioni = await rP.json();

    let assegnazioni = [];
    if (postazioni.length) {
      const ids = postazioni.map(p => p.id).join(',');
      const rA = await sbFetch(SUPA_URL + '/rest/v1/postazione_volontari?select=*,volontari(id,cognome,nome,squadra,telefono)&postazione_id=in.(' + ids + ')&order=id.asc', { headers: H });
      assegnazioni = await rA.json();
    }

    pstPostazioni = postazioni.map(p => ({
      ...p,
      volontari: assegnazioni.filter(a => a.postazione_id === p.id)
    }));

    pstRenderLista();
  } catch(e) {
    list.innerHTML = '<div class="loading-msg bad">Non disponibile.</div>';
  }
}

function pstFiltraLista() {
  pstRenderLista();
}

function _pstTestoRicercabile(p, radioById, mezzoById) {
  const parti = [
    p.numero || '', p.indirizzo || '', p.nome || '',
    p.radio_id && radioById[p.radio_id] ? _pstLabelRadio(radioById[p.radio_id]) : '',
    p.mezzo_id && mezzoById[p.mezzo_id] ? _pstLabelMezzo(mezzoById[p.mezzo_id]) : '',
    (p.volontari || []).map(a => a.volontari ? (a.volontari.cognome + ' ' + a.volontari.nome) : '').join(' ')
  ];
  return parti.join(' ').toLowerCase();
}

function pstRenderLista() {
  const list = document.getElementById('pstList');
  if (!list) return;
  if (!pstPostazioni.length) {
    list.innerHTML = '<div class="loading-msg">nessuna postazione creata per questo intervento. Aggiungine una qui sopra o carica un file Excel.</div>';
    return;
  }
  const assegnatoIn = {};
  pstPostazioni.forEach(p => p.volontari.forEach(a => {
    (assegnatoIn[a.volontario_id] = assegnatoIn[a.volontario_id] || []).push(p.numero || p.indirizzo);
  }));
  const radioById = {}; (tlcData||[]).forEach(t => radioById[t.id] = t);
  const mezzoById = {}; (mezziData||[]).forEach(m => mezzoById[m.id] = m);

  const qEl = document.getElementById('pstSearch');
  const q = qEl ? qEl.value.toLowerCase().trim() : '';
  const postazioniFiltrate = q
    ? pstPostazioni.filter(p => _pstTestoRicercabile(p, radioById, mezzoById).includes(q))
    : pstPostazioni;

  if (!postazioniFiltrate.length) {
    list.innerHTML = '<div class="loading-msg">nessuna postazione corrisponde alla ricerca.</div>';
    return;
  }

  list.innerHTML = postazioniFiltrate.map(p => {
    const nVolAssegnati = p.volontari.length;
    const previsti = p.n_volontari_previsti;
    const contatore = previsti
      ? '<span class="pill ' + (nVolAssegnati < previsti ? 'p-sand' : 'p-blue') + '">' + nVolAssegnati + '/' + previsti + '</span>'
      : '<span class="pill p-grey">' + nVolAssegnati + '</span>';

    const infoRighe = [];
    infoRighe.push(p.radio_id && radioById[p.radio_id] ? '📻 ' + _pstLabelRadio(radioById[p.radio_id]) : '📻 <span class="muted">nessuna radio</span>');
    infoRighe.push(p.vigile_presente ? '👮 Vigile presente' : '👮 <span class="muted">nessun vigile</span>');
    infoRighe.push(p.assegnata_ana === false ? '🏳️ <span class="pill p-sand">non assegnata a noi</span>' : '🏳️ ANA');
    infoRighe.push(p.mezzo_id && mezzoById[p.mezzo_id] ? '🚛 ' + _pstLabelMezzo(mezzoById[p.mezzo_id]) : '🚛 <span class="muted">nessun mezzo</span>');

    const righeVol = p.volontari.length
      ? p.volontari.map(a => {
          const v = a.volontari || {};
          const altrove = (assegnatoIn[a.volontario_id] || []).filter(n => n !== (p.numero || p.indirizzo));
          const warnAltrove = altrove.length ? '<span class="pill p-sand mt6">anche a: ' + altrove.join(', ') + '</span>' : '';
          const tr = a.trasporto || 'piedi';
          const opt = (val, label) => '<option value="' + val + '"' + (tr === val ? ' selected' : '') + '>' + label + '</option>';
          return '<div class="pst-vol">'
            + '<span class="grow"><b>' + (v.cognome||'') + ' ' + (v.nome||'') + '</b>' + (v.squadra ? '<span class="sub">' + v.squadra + '</span>' : '') + warnAltrove + '</span>'
            + '<select aria-label="Trasporto" onchange="pstAggiornaTrasporto(' + a.id + ',this.value)">'
            + opt('piedi','🚶 a piedi') + opt('mezzo_fisso','🚗 con mezzo (resta)') + opt('trasportato','🚐 trasportato')
            + '</select>'
            + '<button class="btn sm danger" aria-label="Rimuovi" onclick="pstRimuoviVolontario(' + a.id + ')">✕</button>'
            + '</div>';
        }).join('')
      : '<div class="loading-msg sm">nessun volontario assegnato</div>';

    const titolo = (p.numero ? p.numero + ' — ' : '') + (p.indirizzo || 'senza indirizzo') + (p.nome ? ' <span class="sub">(' + p.nome + ')</span>' : '');
    const bodyId = 'pstCardBody' + p.id;
    const chevId = 'pstCardChev' + p.id;

    return '<div class="card pst-card">'
      + '<div class="pst-head" onclick="pstToggleCard(' + p.id + ')">'
      + '<h3>' + titolo + '</h3>' + contatore
      + '<button class="btn sm" onclick="event.stopPropagation();pstApriModificaPostazione(' + p.id + ')">Modifica</button>'
      + '<button class="btn sm danger" onclick="event.stopPropagation();pstEliminaPostazione(' + p.id + ')">Elimina</button>'
      + '<span id="' + chevId + '" class="pst-chev">▸</span>'
      + '</div>'
      + '<div id="' + bodyId + '" class="pst-body" style="display:none">'
      + '<div class="pst-info">' + infoRighe.map(r => '<div>' + r + '</div>').join('') + '</div>'
      + '<div class="pst-vols">'
      + '<div class="pst-vols-head"><span class="grp m0">Volontari</span></div>'
      + righeVol
      + '<button class="btn sm mt10" onclick="pstApriAggiungiVolontario(' + p.id + ',\'' + (p.indirizzo||p.numero||'').replace(/'/g,"\\'") + '\')">+ Aggiungi volontario</button>'
      + '</div></div></div>';
  }).join('');
}

function pstToggleCard(id) {
  const body = document.getElementById('pstCardBody' + id);
  const chev = document.getElementById('pstCardChev' + id);
  if (!body) return;
  const aperto = body.style.display === 'grid';
  body.style.display = aperto ? 'none' : 'grid';
  if (chev) chev.textContent = aperto ? '▸' : '▾';
}

function pstToggleNuovaForm() {
  const fields = document.getElementById('pstNuovaFields');
  const btnWrap = document.getElementById('pstNuovaBtnWrap');
  const chevron = document.getElementById('pstNuovaChevron');
  const aperto = fields.style.display === 'grid';
  fields.style.display = aperto ? 'none' : 'grid';
  btnWrap.style.display = aperto ? 'none' : 'block';
  chevron.textContent = aperto ? '▸' : '▾';
}

async function pstNuovaPostazione() {
  if (!pstIntervento) return;
  const numero = (document.getElementById('pstFNumero').value || '').trim();
  const nome = (document.getElementById('pstFNome').value || '').trim();
  const indirizzo = (document.getElementById('pstFIndirizzo').value || '').trim();
  const nVolStr = document.getElementById('pstFNVol').value;
  const radioId = document.getElementById('pstFRadio').value;
  const mezzoId = document.getElementById('pstFMezzo').value;
  const vigile = document.getElementById('pstFVigile').checked;
  const ana = document.getElementById('pstFAna').checked;
  if (!numero && !indirizzo) { alert('Inserisci almeno un numero o un indirizzo per la postazione.'); return; }

  const ordine = pstPostazioni.length ? Math.max(...pstPostazioni.map(p => p.ordine || 0)) + 1 : 1;
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/postazioni', {
      method: 'POST',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({
        intervento_id: pstIntervento.id, ordine,
        numero: numero || null,
        nome: nome || null,
        indirizzo: indirizzo || null,
        n_volontari_previsti: nVolStr ? parseInt(nVolStr, 10) : null,
        radio_id: radioId ? parseInt(radioId, 10) : null,
        mezzo_id: mezzoId ? parseInt(mezzoId, 10) : null,
        vigile_presente: vigile,
        assegnata_ana: ana
      })
    });
    if (!res.ok) throw new Error();
    ['pstFNumero','pstFNome','pstFIndirizzo','pstFNVol'].forEach(id => document.getElementById(id).value = '');
    document.getElementById('pstFRadio').value = '';
    document.getElementById('pstFMezzo').value = '';
    document.getElementById('pstFVigile').checked = false;
    document.getElementById('pstFAna').checked = true;
    pstToggleNuovaForm();
    await pstCaricaLista();
  } catch(e) { alert('Errore nella creazione della postazione.'); }
}

function pstApriModificaPostazione(id) {
  const p = pstPostazioni.find(x => x.id === id);
  if (!p) return;
  document.getElementById('pstEFId').value = p.id;
  document.getElementById('pstEFNumero').value = p.numero || '';
  document.getElementById('pstEFNome').value = p.nome || '';
  document.getElementById('pstEFIndirizzo').value = p.indirizzo || '';
  document.getElementById('pstEFNVol').value = p.n_volontari_previsti || '';
  document.getElementById('pstEFRadio').value = p.radio_id || '';
  document.getElementById('pstEFMezzo').value = p.mezzo_id || '';
  document.getElementById('pstEFVigile').checked = !!p.vigile_presente;
  document.getElementById('pstEFAna').checked = p.assegnata_ana !== false;
  document.getElementById('pstEditOverlay').classList.add('open');
}

async function pstSalvaModificaPostazione() {
  const id = document.getElementById('pstEFId').value;
  const numero = (document.getElementById('pstEFNumero').value || '').trim();
  const nome = (document.getElementById('pstEFNome').value || '').trim();
  const indirizzo = (document.getElementById('pstEFIndirizzo').value || '').trim();
  const nVolStr = document.getElementById('pstEFNVol').value;
  const radioId = document.getElementById('pstEFRadio').value;
  const mezzoId = document.getElementById('pstEFMezzo').value;
  const vigile = document.getElementById('pstEFVigile').checked;
  const ana = document.getElementById('pstEFAna').checked;
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + id, {
      method: 'PATCH',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({
        numero: numero || null, nome: nome || null, indirizzo: indirizzo || null,
        n_volontari_previsti: nVolStr ? parseInt(nVolStr, 10) : null,
        radio_id: radioId ? parseInt(radioId, 10) : null,
        mezzo_id: mezzoId ? parseInt(mezzoId, 10) : null,
        vigile_presente: vigile,
        assegnata_ana: ana
      })
    });
    if (!res.ok) throw new Error();
    document.getElementById('pstEditOverlay').classList.remove('open');
    await pstCaricaLista();
  } catch(e) { alert('Errore nel salvataggio.'); }
}

async function pstEliminaPostazione(id) {
  if (!confirm('Eliminare questa postazione e tutte le assegnazioni collegate?')) return;
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + id, { method: 'DELETE', headers: H });
    await pstCaricaLista();
  } catch(e) { alert('Errore durante l\'eliminazione.'); }
}

async function pstEliminaTutte() {
  if (!pstIntervento || !pstPostazioni.length) { alert('Non ci sono postazioni da eliminare per questo intervento.'); return; }
  const n = pstPostazioni.length;
  if (!confirm('Eliminare TUTTE le ' + n + ' postazioni di questo intervento (e tutte le assegnazioni volontari collegate)? L\'operazione non è reversibile.')) return;
  if (!confirm('Ultima conferma: procedere con l\'eliminazione di tutte le ' + n + ' postazioni?')) return;
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazioni?intervento_id=eq.' + pstIntervento.id, { method: 'DELETE', headers: H });
    const searchEl = document.getElementById('pstSearch');
    if (searchEl) searchEl.value = '';
    await pstCaricaLista();
  } catch(e) { alert('Errore durante l\'eliminazione massiva.'); }
}

async function pstAggiornaTrasporto(assegnazioneId, valore) {
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazione_volontari?id=eq.' + assegnazioneId, {
      method: 'PATCH', headers: HJ, body: JSON.stringify({ trasporto: valore })
    });
    pstPostazioni.forEach(p => { const a = p.volontari.find(x => x.id === assegnazioneId); if (a) a.trasporto = valore; });
  } catch(e) { alert('Errore nel salvataggio del trasporto.'); }
}

async function pstRimuoviVolontario(assegnazioneId) {
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazione_volontari?id=eq.' + assegnazioneId, { method: 'DELETE', headers: H });
    await pstCaricaLista();
  } catch(e) { alert('Errore durante la rimozione.'); }
}

async function pstApriAggiungiVolontario(postazioneId, nomePostazione) {
  pstTargetPostazioneId = postazioneId;
  document.getElementById('pstAddVolTitle').textContent = 'Aggiungi volontario — ' + nomePostazione;
  document.getElementById('pstAddVolSearch').value = '';
  if (!pstVolontariIntervento.length) await pstCaricaVolontariIntervento();
  pstRenderModalList();
  document.getElementById('pstAddVolOverlay').classList.add('open');
}

function pstChiudiModaleVol() {
  document.getElementById('pstAddVolOverlay').classList.remove('open');
  pstTargetPostazioneId = null;
}

function pstRenderModalList() {
  const box = document.getElementById('pstAddVolList');
  const q = (document.getElementById('pstAddVolSearch').value || '').toLowerCase().trim();
  const postaz = pstPostazioni.find(p => p.id === pstTargetPostazioneId);
  const giaQui = new Set((postaz ? postaz.volontari : []).map(a => a.volontario_id));

  const filtrati = pstVolontariIntervento.filter(v => {
    if (!q) return true;
    return ((v.cognome||'') + ' ' + (v.nome||'') + ' ' + (v.squadra||'')).toLowerCase().includes(q);
  });

  if (!filtrati.length) { box.innerHTML = '<div class="loading-msg">nessun volontario trovato tra i partecipanti a questo intervento.</div>'; return; }

  box.innerHTML = filtrati.map(v => {
    const assegnato = giaQui.has(v.id);
    return '<div class="lr">'
      + '<span class="mid"><b>' + (v.cognome||'') + ' ' + (v.nome||'') + '</b>' + (v.squadra ? '<span class="sub">' + v.squadra + '</span>' : '') + '</span>'
      + (assegnato
          ? '<span class="pill p-blue">Assegnato</span>'
          : '<button class="btn sm" onclick="pstAggiungiVolontarioA(' + v.id + ')">Aggiungi</button>')
      + '</div>';
  }).join('');
}

async function pstAggiungiVolontarioA(volontarioId) {
  if (!pstTargetPostazioneId) return;
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/postazione_volontari', {
      method: 'POST',
      headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
      body: JSON.stringify({ postazione_id: pstTargetPostazioneId, volontario_id: volontarioId })
    });
    if (!res.ok) throw new Error();
    await pstCaricaLista();
    pstRenderModalList();
  } catch(e) { alert('Errore durante l\'assegnazione (forse è già presente in questa postazione).'); }
}

// -- ESPORTAZIONE ELENCO ATTUALE --
async function pstEsportaExcel() {
  if (!pstIntervento || !pstPostazioni.length) { alert('Nessuna postazione da esportare.'); return; }
  try { await caricaExcelJS(); } catch(e) { alert('Impossibile caricare la libreria Excel.'); return; }
  const radioById = {}; (tlcData||[]).forEach(t => radioById[t.id] = t);
  const mezzoById = {}; (mezziData||[]).forEach(m => mezzoById[m.id] = m);

  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet('Postazioni');
  ws.columns = [
    { header: 'Numero',    key: 'numero',    width: 12 },
    { header: 'Indirizzo', key: 'indirizzo', width: 26 },
    { header: 'Tag',       key: 'tag',       width: 20 },
    { header: 'Radio',     key: 'radio',     width: 22 },
    { header: 'Mezzo',     key: 'mezzo',     width: 22 },
    { header: 'Vigile',    key: 'vigile',    width: 10 },
    { header: 'ANA',       key: 'ana',       width: 8  },
    { header: 'Cognome',   key: 'cognome',   width: 18 },
    { header: 'Nome vol.', key: 'nome',      width: 16 },
    { header: 'Squadra',   key: 'squadra',   width: 14 },
    { header: 'Telefono',  key: 'telefono',  width: 16 },
    { header: 'Trasporto', key: 'trasporto', width: 16 },
  ];
  ws.getRow(1).font = { bold: true };
  const trasportoLbl = { mezzo_fisso: 'Con mezzo (resta)', trasportato: 'Trasportato', piedi: 'A piedi' };
  pstPostazioni.forEach(p => {
    const base = {
      numero: p.numero || '', indirizzo: p.indirizzo || '', tag: p.nome || '',
      radio: p.radio_id && radioById[p.radio_id] ? _pstLabelRadio(radioById[p.radio_id]) : '',
      mezzo: p.mezzo_id && mezzoById[p.mezzo_id] ? _pstLabelMezzo(mezzoById[p.mezzo_id]) : '',
      vigile: p.vigile_presente ? 'Sì' : 'No',
      ana: p.assegnata_ana === false ? 'No' : 'Sì'
    };
    if (!p.volontari.length) {
      ws.addRow(Object.assign({ cognome:'', nome:'', squadra:'', telefono:'', trasporto:'' }, base));
    } else {
      p.volontari.forEach(a => {
        const v = a.volontari || {};
        ws.addRow(Object.assign({ cognome: v.cognome||'', nome: v.nome||'', squadra: v.squadra||'', telefono: v.telefono||'', trasporto: trasportoLbl[a.trasporto||'piedi'] }, base));
      });
    }
  });

  const out = await wb.xlsx.writeBuffer();
  const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const safeName = (pstIntervento.evento || 'evento').replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 40);
  a.href = url;
  a.download = 'Postazioni_' + safeName + '.xlsx';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// -- ESPORTAZIONE PDF (griglia postazioni, stile report Varchi) --
function pstEsportaPDF() {
  if (!pstIntervento || !pstPostazioni.length) { alert('Nessuna postazione da esportare.'); return; }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const W = 297, H = 210, mg = 8;
  const GREEN = [15, 110, 86], BLACK = [20, 20, 20], GRAY = [110, 110, 110], LIGHTROW = [240, 248, 245];

  const radioById = {}; (tlcData || []).forEach(t => radioById[t.id] = t);
  const mezzoById = {}; (mezziData || []).forEach(m => mezzoById[m.id] = m);

  const dataStr = pstIntervento.data ? new Date(pstIntervento.data).toLocaleDateString('it-IT') : '';
  const sottotitolo = (pstIntervento.evento || '') + (dataStr ? ' — ' + dataStr : '') + (pstIntervento.luogo ? ' (' + pstIntervento.luogo + ')' : '');

  // Colonne: label, larghezza (mm)
  const cols = [
    { key: 'numero', label: 'N°', w: 12 },
    { key: 'indirizzo', label: 'Indirizzo', w: 45 },
    { key: 'tag', label: 'Tag', w: 22 },
    { key: 'radio', label: 'Radio', w: 32 },
    { key: 'mezzo', label: 'Mezzo', w: 32 },
    { key: 'vigile', label: 'Vigile', w: 14 },
    { key: 'ana', label: 'ANA', w: 12 },
    { key: 'contatore', label: 'Vol.', w: 14 },
    { key: 'volontari', label: 'Volontari (nome, telefono)', w: W - mg * 2 - (12+45+22+32+32+14+12+14) }
  ];
  const colX = []; let acc = mg; cols.forEach(c => { colX.push(acc); acc += c.w; });

  function disegnaHeader() {
    doc.setFillColor(...GREEN); doc.rect(0, 0, W, 20, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
    doc.text('GESTIONE POSTAZIONI', mg, 9);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.text(sottotitolo, mg, 15);
    doc.setFontSize(7.5);
    doc.text('Stampato il ' + new Date().toLocaleDateString('it-IT'), W - mg, 15, { align: 'right' });

    let y = 25;
    doc.setFillColor(...GREEN);
    doc.rect(mg, y, W - mg * 2, 6, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    cols.forEach((c, i) => doc.text(c.label, colX[i] + 1.5, y + 4));
    return y + 6;
  }

  let y = disegnaHeader();
  let rowIdx = 0;

  pstPostazioni.forEach(p => {
    const radioLbl = p.radio_id && radioById[p.radio_id] ? _pstLabelRadio(radioById[p.radio_id]) : '—';
    const mezzoLbl = p.mezzo_id && mezzoById[p.mezzo_id] ? _pstLabelMezzo(mezzoById[p.mezzo_id]) : '—';
    const iconTr = { mezzo_fisso: '[M]', trasportato: '[T]', piedi: '[P]' };
    const volTesto = p.volontari.length
      ? p.volontari.map(a => { const v = a.volontari || {}; return iconTr[a.trasporto||'piedi'] + ' ' + (v.cognome || '') + ' ' + (v.nome || '') + (v.telefono ? ' (' + v.telefono + ')' : ''); }).join('  •  ')
      : 'nessuno';

    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    const volLines = doc.splitTextToSize(volTesto, cols[8].w - 3);
    const indLines = doc.splitTextToSize(p.indirizzo || '—', cols[1].w - 3);
    const nRighe = Math.max(volLines.length, indLines.length, 1);
    const rowH = Math.max(7, nRighe * 3.6 + 2);

    if (y + rowH > H - mg - 6) { doc.addPage(); y = disegnaHeader(); rowIdx = 0; }

    if (rowIdx % 2 === 1) { doc.setFillColor(...LIGHTROW); doc.rect(mg, y, W - mg * 2, rowH, 'F'); }
    doc.setDrawColor(210, 210, 210); doc.setLineWidth(0.15);
    doc.line(mg, y + rowH, W - mg, y + rowH);

    doc.setTextColor(...BLACK);
    doc.setFont('helvetica', 'bold'); doc.text(p.numero || '—', colX[0] + 1.5, y + 4.5);
    doc.setFont('helvetica', 'normal');
    doc.text(indLines, colX[1] + 1.5, y + 4.5);
    doc.text(p.nome || '—', colX[2] + 1.5, y + 4.5, { maxWidth: cols[2].w - 3 });
    doc.text(radioLbl, colX[3] + 1.5, y + 4.5, { maxWidth: cols[3].w - 3 });
    doc.text(mezzoLbl, colX[4] + 1.5, y + 4.5, { maxWidth: cols[4].w - 3 });
    doc.setTextColor(p.vigile_presente ? 6 : 150, p.vigile_presente ? 130 : 150, p.vigile_presente ? 150 : 150);
    doc.text(p.vigile_presente ? 'Sì' : 'No', colX[5] + 1.5, y + 4.5);
    doc.setTextColor(...(p.assegnata_ana === false ? [200, 120, 0] : BLACK));
    doc.text(p.assegnata_ana === false ? 'No' : 'Sì', colX[6] + 1.5, y + 4.5);
    doc.setTextColor(...GRAY);
    doc.text(String(p.volontari.length) + (p.n_volontari_previsti ? '/' + p.n_volontari_previsti : ''), colX[7] + 1.5, y + 4.5);
    doc.setTextColor(...BLACK);
    doc.text(volLines, colX[8] + 1.5, y + 4.5);

    y += rowH;
    rowIdx++;
  });

  const totVol = pstPostazioni.reduce((s, p) => s + p.volontari.length, 0);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(...GRAY);
  doc.text(pstPostazioni.length + ' postazioni — ' + totVol + ' volontari assegnati   |   [M] con mezzo (resta)   [T] trasportato   [P] a piedi', mg, H - 4);

  const safeName = (pstIntervento.evento || 'evento').replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 40);
  doc.save('Postazioni_' + safeName + '.pdf');
}

// -- SCARICA MODELLO PER CREAZIONE MASSIVA --
async function pstScaricaModello() {
  if (!pstIntervento) { alert('Seleziona prima un intervento.'); return; }
  try { await caricaExcelJS(); } catch(e) { alert('Impossibile caricare la libreria Excel.'); return; }
  await _pstCaricaRadioMezzoOpts();

  const wb = new ExcelJS.Workbook();

  const ws = wb.addWorksheet('Postazioni da creare');
  ws.columns = [
    { header: 'Numero',                key: 'numero',    width: 12 },
    { header: 'Indirizzo',             key: 'indirizzo', width: 26 },
    { header: 'Tag (opzionale)',       key: 'tag',       width: 20 },
    { header: 'N. Volontari Previsti', key: 'nvol',      width: 20 },
    { header: 'Radio (copia da foglio Riferimenti)', key: 'radio', width: 30 },
    { header: 'Mezzo (copia da foglio Riferimenti)', key: 'mezzo', width: 30 },
    { header: 'Volontari (Cognome Nome; separati da ;)', key: 'volontari', width: 45 },
  ];
  ws.getRow(1).font = { bold: true };
  ws.addRow({ numero: 'T3', indirizzo: 'Via Roma 5', tag: 'Partenza', nvol: 2, radio: '', mezzo: '', volontari: 'Rossi Mario; Bianchi Luca' });

  const wsRef = wb.addWorksheet('Riferimenti');
  wsRef.columns = [
    { header: 'Volontari intervento', key: 'vol', width: 30 },
    { header: '', key: 'sep1', width: 3 },
    { header: 'Radio disponibili', key: 'radio', width: 30 },
    { header: '', key: 'sep2', width: 3 },
    { header: 'Mezzi disponibili', key: 'mezzo', width: 30 },
  ];
  wsRef.getRow(1).font = { bold: true };
  const nRighe = Math.max(pstVolontariIntervento.length, tlcData.length, mezziData.length, 1);
  for (let i = 0; i < nRighe; i++) {
    const v = pstVolontariIntervento[i];
    const t = tlcData[i];
    const m = mezziData[i];
    wsRef.addRow({
      vol: v ? (v.cognome + ' ' + v.nome) : '',
      radio: t ? _pstLabelRadio(t) : '',
      mezzo: m ? _pstLabelMezzo(m) : ''
    });
  }

  const out = await wb.xlsx.writeBuffer();
  const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const safeName = (pstIntervento.evento || 'evento').replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 40);
  a.href = url;
  a.download = 'ModelloPostazioni_' + safeName + '.xlsx';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// -- IMPORTAZIONE MASSIVA --
function _pstNorm(s) {
  return (s || '').toString().toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Z]/g, '');
}

async function pstImportaExcel(file) {
  if (!file || !pstIntervento) return;
  const status = document.getElementById('pstImportStatus');
  status.style.display = 'block';
  status.innerHTML = '<div class="loading-msg">importazione in corso...</div>';
  try { await caricaExcelJS(); } catch(e) { status.innerHTML = '<div class="loading-msg bad">impossibile caricare la libreria Excel.</div>'; return; }

  try {
    const buf = await file.arrayBuffer();
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(buf);
    const ws = wb.getWorksheet('Postazioni da creare') || wb.worksheets[0];

    const righe = [];
    ws.eachRow((row, num) => {
      if (num === 1) return; // header
      const val = (c) => (c && c.value !== null && c.value !== undefined) ? String(c.value).trim() : '';
      const numero = val(row.getCell(1));
      const indirizzo = val(row.getCell(2));
      const nome = val(row.getCell(3));
      const nvolRaw = val(row.getCell(4));
      const radioLabel = val(row.getCell(5));
      const mezzoLabel = val(row.getCell(6));
      const volontariRaw = val(row.getCell(7));
      if (!numero && !indirizzo && !nome && !volontariRaw) return; // riga vuota
      righe.push({ numero, nome, indirizzo, nvol: nvolRaw ? parseInt(nvolRaw, 10) : null, radioLabel, mezzoLabel, volontariRaw });
    });

    if (!righe.length) { status.innerHTML = '<div class="loading-msg bad">nessuna riga valida trovata nel file.</div>'; return; }

    await _pstCaricaRadioMezzoOpts();
    if (!pstVolontariIntervento.length) await pstCaricaVolontariIntervento();

    let creati = 0;
    const avvisi = [];
    const ordineBase = pstPostazioni.length ? Math.max(...pstPostazioni.map(p => p.ordine || 0)) + 1 : 1;

    for (let idx = 0; idx < righe.length; idx++) {
      const r = righe[idx];

      let radioId = null;
      if (r.radioLabel) {
        const match = (tlcData||[]).find(t => _pstLabelRadio(t).toLowerCase() === r.radioLabel.toLowerCase()) ||
                      (tlcData||[]).find(t => _pstNorm(_pstLabelRadio(t)).includes(_pstNorm(r.radioLabel)));
        if (match) radioId = match.id; else avvisi.push('Riga ' + (idx+2) + ': radio "' + r.radioLabel + '" non trovata');
      }
      let mezzoId = null;
      if (r.mezzoLabel) {
        const match = (mezziData||[]).find(m => _pstLabelMezzo(m).toLowerCase() === r.mezzoLabel.toLowerCase()) ||
                      (mezziData||[]).find(m => _pstNorm(_pstLabelMezzo(m)).includes(_pstNorm(r.mezzoLabel)));
        if (match) mezzoId = match.id; else avvisi.push('Riga ' + (idx+2) + ': mezzo "' + r.mezzoLabel + '" non trovato');
      }

      let postazioneId;
      try {
        const res = await sbFetch(SUPA_URL + '/rest/v1/postazioni', {
          method: 'POST',
          headers: Object.assign({}, HJ, { 'Prefer': 'return=representation' }),
          body: JSON.stringify({
            intervento_id: pstIntervento.id, ordine: ordineBase + idx,
            numero: r.numero || null, nome: r.nome || null, indirizzo: r.indirizzo || null,
            n_volontari_previsti: r.nvol, radio_id: radioId, mezzo_id: mezzoId
          })
        });
        if (!res.ok) throw new Error();
        const created = await res.json();
        postazioneId = created[0].id;
        creati++;
      } catch(e) { avvisi.push('Riga ' + (idx+2) + ': errore nella creazione della postazione'); continue; }

      if (r.volontariRaw) {
        const nomiRichiesti = r.volontariRaw.split(';').map(s => s.trim()).filter(Boolean);
        for (const nomeRichiesto of nomiRichiesti) {
          const target = _pstNorm(nomeRichiesto);
          const match = pstVolontariIntervento.find(v => _pstNorm(v.cognome + v.nome) === target || _pstNorm(v.nome + v.cognome) === target);
          if (!match) { avvisi.push('Riga ' + (idx+2) + ': volontario "' + nomeRichiesto + '" non trovato tra i partecipanti all\'intervento'); continue; }
          try {
            await sbFetch(SUPA_URL + '/rest/v1/postazione_volontari', {
              method: 'POST',
              headers: Object.assign({}, HJ, { 'Prefer': 'return=minimal' }),
              body: JSON.stringify({ postazione_id: postazioneId, volontario_id: match.id })
            });
          } catch(e) { avvisi.push('Riga ' + (idx+2) + ': errore assegnando "' + nomeRichiesto + '"'); }
        }
      }
    }

    let html = '<div class="loading-msg">✔ ' + creati + ' postazioni create.' + (avvisi.length ? ' ⚠ ' + avvisi.length + ' avvisi.' : '') + '</div>';
    if (avvisi.length) {
      html += '<details class="pst-avvisi mt6"><summary>Vedi avvisi</summary>'
        + '<ul>' + avvisi.map(a => '<li>' + a + '</li>').join('') + '</ul></details>';
    }
    status.innerHTML = html;
    document.getElementById('pstFileInput').value = '';
    await pstCaricaLista();
  } catch(e) {
    status.innerHTML = '<div class="loading-msg bad">errore durante la lettura del file: ' + e.message + '</div>';
  }
}

// -- MAPPA POSTAZIONI --
let pstMappaData = null;
let pstMapModalitaDisegno = false;
let pstMapArmaPartenza = false;
let pstMapArmaArrivo = false;
let pstMapArmedPostazioneId = null;
let pstMapGoogleInstance = null;
let pstMapGoogleMarkers = {};
let pstMapGooglePolyline = null;
let pstMapGoogleClickListener = null;
let pstDragLabel = null; // { postazioneId, startX, startY, origDx, origDy, moved }
let pstPanState = null;  // { startX, startY, scrollLeft, scrollTop, moved }

function pstSetTabActive(id, active) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.toggle('on', !!active);
}

function pstMostraTab(tab) {
  document.getElementById('pstViewElenco').style.display = tab === 'elenco' ? 'block' : 'none';
  document.getElementById('pstViewMappa').style.display = tab === 'mappa' ? 'block' : 'none';
  pstSetTabActive('pstTabElenco', tab === 'elenco');
  pstSetTabActive('pstTabMappa', tab === 'mappa');
  if (tab === 'mappa') pstInitMappa();
}

async function pstInitMappa() {
  if (!pstIntervento) return;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/mappe_intervento?select=*&intervento_id=eq.' + pstIntervento.id, { headers: H });
    const rows = await r.json();
    pstMappaData = (Array.isArray(rows) && rows.length) ? rows[0] : { intervento_id: pstIntervento.id, tipo: 'immagine', immagine_url: null, google_center_lat: null, google_center_lng: null, google_zoom: 15, percorso: [] };
  } catch(e) {
    pstMappaData = { intervento_id: pstIntervento.id, tipo: 'immagine', percorso: [] };
  }
  await pstFirmaMappa();
  document.getElementById('pstMapTipo').value = pstMappaData.tipo || 'immagine';
  pstMapModalitaDisegno = false;
  pstMapArmaPartenza = false;
  pstMapArmaArrivo = false;
  pstMapArmedPostazioneId = null;
  document.getElementById('pstMapStatus').textContent = '';
  document.getElementById('pstBtnDisegnaPercorso').textContent = '✏️ Disegna percorso';
  pstSetTabActive('pstBtnPartenza', false);
  pstSetTabActive('pstBtnArrivo', false);
  pstAggiornaControlliTipoMappa();
  pstRenderListePosizionamento();
}

function pstAggiornaControlliTipoMappa() {
  const tipo = document.getElementById('pstMapTipo').value;
  document.getElementById('pstMapImmagineControls').style.display = tipo === 'immagine' ? 'flex' : 'none';
  document.getElementById('pstMapGoogleControls').style.display = tipo === 'google' ? 'block' : 'none';
  if (tipo === 'google') {
    const savedKey = localStorage.getItem('pst_gmaps_key');
    if (savedKey) document.getElementById('pstMapApiKey').value = savedKey;
    pstRenderCanvasGoogle();
  } else {
    pstRenderCanvasImmagine();
  }
}

async function pstCambiaTipoMappa() {
  const tipo = document.getElementById('pstMapTipo').value;
  pstMappaData.tipo = tipo;
  await pstUpsertMappa({ tipo: tipo });
  pstAggiornaControlliTipoMappa();
}

async function pstFirmaMappa() {
  if (pstMappaData) pstMappaData._img = pstMappaData.immagine_url ? await sbUrlFile(pstMappaData.immagine_url) : null;
}

async function pstUpsertMappa(campi) {
  if (!pstIntervento) return;
  const body = Object.assign({ intervento_id: pstIntervento.id }, campi);
  try {
    const res = await sbFetch(SUPA_URL + '/rest/v1/mappe_intervento?on_conflict=intervento_id', {
      method: 'POST',
      headers: Object.assign({}, HJ, { 'Prefer': 'resolution=merge-duplicates,return=representation' }),
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (Array.isArray(data) && data.length) { pstMappaData = data[0]; await pstFirmaMappa(); }
  } catch(e) {}
}

async function pstCaricaImmagineMappa(file) {
  if (!file || !pstIntervento) return;
  try {
    const path = pstIntervento.id + '/mappa_' + Date.now() + '_' + file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
    const up = await sbFetch(SUPA_URL + '/storage/v1/object/mappe-postazioni/' + path, {
      method: 'POST', headers: { 'apikey': SUPA_KEY, 'Content-Type': file.type }, body: file
    });
    if (!up.ok) throw new Error('upload fallito');
    const url = sbPercorso('mappe-postazioni', path);
    await pstUpsertMappa({ immagine_url: url, tipo: 'immagine' });
    document.getElementById('pstMapTipo').value = 'immagine';
    pstAggiornaControlliTipoMappa();
  } catch(e) { alert('Errore nel caricamento dell\'immagine.'); }
}

let pstImgZoom = 1;
const PST_IMG_BASE_WIDTH = 1000; // px, larghezza di riferimento non scalata dell'immagine

function pstRenderCanvasImmagine() {
  const canvas  = document.getElementById('pstMapCanvas');
  const noImg   = document.getElementById('pstMapNessunaImmagine');
  const layout  = document.getElementById('pstMapLayout');
  const toolbar = document.getElementById('pstMapToolbar');
  const zoomCtrl = document.getElementById('pstMapZoomControls');
  const btnScarica = document.getElementById('pstBtnScaricaMappa');
  if (!pstMappaData || !pstMappaData._img) {
    layout.style.display = 'none';
    toolbar.style.display = 'none';
    noImg.textContent = pstMappaData && pstMappaData.immagine_url ? 'File non disponibile. Puoi caricare di nuovo l\'immagine.' : 'Carica un\'immagine per iniziare a posizionare le postazioni.';
    noImg.style.display = 'block';
    noImg.textContent = 'carica un\'immagine per iniziare a posizionare le postazioni.';
    return;
  }
  noImg.style.display = 'none';
  layout.style.display = 'block';
  toolbar.style.display = 'flex';
  zoomCtrl.style.display = 'inline-flex';
  btnScarica.style.display = 'inline-block';
  document.getElementById('pstBtnScaricaMappeAna').style.display = 'inline-block';
  document.getElementById('pstSpessorePercorso').value = pstMappaData.route_thickness || 3;

  const spessore = ((pstMappaData.route_thickness || 3) * 0.1);
  const percorso = pstMappaData.percorso || [];
  const puntiSvg = percorso.map(p => p.x + ',' + p.y).join(' ');

  const bandiera = (x, y, emoji, colore) => {
    return '<div class="pst-flag" style="left:' + x + '%;top:' + y + '%">' + emoji + '</div>';
  };
  const partenzaHtml = (pstMappaData.partenza_x != null) ? bandiera(pstMappaData.partenza_x, pstMappaData.partenza_y, '🚩') : '';
  const arrivoHtml = (pstMappaData.arrivo_x != null) ? bandiera(pstMappaData.arrivo_x, pstMappaData.arrivo_y, '🏁') : '';

  const pins = pstPostazioni.filter(p => p.map_x != null && p.map_y != null).map(p => {
    const numero = p.numero || ('#' + p.id);
    const dx = (p.label_dx != null) ? p.label_dx : 10;
    const dy = (p.label_dy != null) ? p.label_dy : -40;
    const lunghezza = Math.sqrt(dx * dx + dy * dy);
    const angolo = Math.atan2(dy, dx) * 180 / Math.PI;
    const haVol = p.volontari.length > 0;
    const haVigile = !!p.vigile_presente;
    const statoCls = (haVol ? ' vol' : '') + (haVigile ? ' vig' : '') + (p.assegnata_ana === false ? ' non-ana' : '');

    // posizioni e angoli calcolati dai dati: restano inline, l'aspetto sta nelle classi pst-*
    return '<div class="pst-map-pin" data-pid="' + p.id + '" data-dx="' + dx + '" data-dy="' + dy + '" style="left:' + p.map_x + '%;top:' + p.map_y + '%">'
      + '<div class="pst-pin-dot"></div>'
      + '<div class="pst-pin-line" style="width:' + lunghezza + 'px;transform:rotate(' + angolo + 'deg)"></div>'
      + '<div class="pst-map-pin-label' + statoCls + '" style="left:' + dx + 'px;top:' + dy + 'px">' + numero + '</div>'
      + '</div>';
  }).join('');

  canvas.innerHTML =
    '<div id="pstMapZoomWrap" class="pst-zoomwrap" style="width:' + PST_IMG_BASE_WIDTH + 'px;transform:scale(' + pstImgZoom + ')">'
    + '<img id="pstMapImgEl" class="pst-img" src="' + pstMappaData._img + '" style="width:' + PST_IMG_BASE_WIDTH + 'px" draggable="false" alt="">'
    + '<svg id="pstMapSvg" class="pst-svg" viewBox="0 0 100 100" preserveAspectRatio="none">'
    + (puntiSvg ? '<polyline class="pst-route" points="' + puntiSvg + '" stroke-width="' + spessore + '" vector-effect="non-scaling-stroke" />' : '')
    + '</svg>'
    + partenzaHtml + arrivoHtml
    + pins
    + '</div>';

  const zoomWrap = document.getElementById('pstMapZoomWrap');

  // Click (posiziona punto/pin) vs Drag (pan) — distinti per soglia di movimento
  canvas.onmousedown = (e) => {
    if (e.target.closest('.pst-map-pin-label')) return; // gestito dal drag etichetta
    pstPanState = { startX: e.clientX, startY: e.clientY, scrollLeft: canvas.scrollLeft, scrollTop: canvas.scrollTop, moved: false, zoomWrap };
  };

  // Zoom con Ctrl + rotella, ancorato al cursore
  canvas.onwheel = (e) => {
    if (!e.ctrlKey) return;
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left, mouseY = e.clientY - rect.top;
    const baseX = (canvas.scrollLeft + mouseX) / pstImgZoom;
    const baseY = (canvas.scrollTop + mouseY) / pstImgZoom;
    pstImgZoom = Math.max(0.5, Math.min(4, Math.round((pstImgZoom + (e.deltaY < 0 ? 0.15 : -0.15)) * 100) / 100));
    zoomWrap.style.transform = 'scale(' + pstImgZoom + ')';
    document.getElementById('pstMapZoomLabel').textContent = Math.round(pstImgZoom * 100) + '%';
    canvas.scrollLeft = baseX * pstImgZoom - mouseX;
    canvas.scrollTop = baseY * pstImgZoom - mouseY;
  };

  // Drag etichetta postazione
  zoomWrap.querySelectorAll('.pst-map-pin-label').forEach(el => {
    el.addEventListener('mousedown', (ev) => {
      ev.stopPropagation();
      ev.preventDefault();
      const pinEl = el.closest('.pst-map-pin');
      pstDragLabel = {
        postazioneId: parseInt(pinEl.getAttribute('data-pid'), 10),
        startX: ev.clientX, startY: ev.clientY,
        origDx: parseFloat(pinEl.getAttribute('data-dx')), origDy: parseFloat(pinEl.getAttribute('data-dy')),
        moved: false, el
      };
      el.classList.add('dragging');
    });
  });
}

function pstGestisciPanMove(e) {
  if (pstDragLabel) {
    const dx = (e.clientX - pstDragLabel.startX) / pstImgZoom;
    const dy = (e.clientY - pstDragLabel.startY) / pstImgZoom;
    if (Math.abs(dx) > 2 || Math.abs(dy) > 2) pstDragLabel.moved = true;
    const nuovaDx = pstDragLabel.origDx + dx, nuovaDy = pstDragLabel.origDy + dy;
    pstDragLabel.el.style.left = nuovaDx + 'px';
    pstDragLabel.el.style.top = nuovaDy + 'px';
    return;
  }
  if (pstPanState) {
    const dx = e.clientX - pstPanState.startX, dy = e.clientY - pstPanState.startY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) pstPanState.moved = true;
    if (pstPanState.moved) {
      const canvas = document.getElementById('pstMapCanvas');
      if (canvas) { canvas.scrollLeft = pstPanState.scrollLeft - dx; canvas.scrollTop = pstPanState.scrollTop - dy; }
    }
  }
}

async function pstGestisciPanEnd(e) {
  if (pstDragLabel) {
    const drag = pstDragLabel;
    pstDragLabel = null;
    if (drag.el) drag.el.classList.remove('dragging');
    if (drag.moved) {
      const dx = (e.clientX - drag.startX) / pstImgZoom;
      const dy = (e.clientY - drag.startY) / pstImgZoom;
      const nuovaDx = Math.round(drag.origDx + dx), nuovaDy = Math.round(drag.origDy + dy);
      const p = pstPostazioni.find(x => x.id === drag.postazioneId);
      if (p) { p.label_dx = nuovaDx; p.label_dy = nuovaDy; }
      try {
        await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + drag.postazioneId, {
          method: 'PATCH', headers: HJ, body: JSON.stringify({ label_dx: nuovaDx, label_dy: nuovaDy })
        });
      } catch(err) {}
      pstRenderCanvasImmagine();
    } else {
      if (confirm('Rimuovere questa postazione dalla mappa?')) pstRimuoviDallaMappa(drag.postazioneId);
    }
    return;
  }
  if (pstPanState) {
    const pan = pstPanState;
    pstPanState = null;
    if (!pan.moved && pan.zoomWrap && document.body.contains(pan.zoomWrap)) {
      pstGestisciClickImmagine(e, pan.zoomWrap);
    }
  }
}

document.addEventListener('mousemove', (e) => pstGestisciPanMove(e));
document.addEventListener('mouseup', (e) => pstGestisciPanEnd(e));

function pstGestisciClickImmagine(e, zoomWrap) {
  const rect = zoomWrap.getBoundingClientRect();
  let xPct = (e.clientX - rect.left) / rect.width * 100;
  let yPct = (e.clientY - rect.top) / rect.height * 100;
  xPct = Math.max(0, Math.min(100, Math.round(xPct * 10) / 10));
  yPct = Math.max(0, Math.min(100, Math.round(yPct * 10) / 10));

  if (pstMapModalitaDisegno) {
    const percorso = (pstMappaData.percorso || []).slice();
    percorso.push({ x: xPct, y: yPct });
    pstMappaData.percorso = percorso;
    pstUpsertMappa({ percorso: percorso });
    pstRenderCanvasImmagine();
  } else if (pstMapArmaPartenza) {
    pstMappaData.partenza_x = xPct; pstMappaData.partenza_y = yPct;
    pstUpsertMappa({ partenza_x: xPct, partenza_y: yPct });
    pstMapArmaPartenza = false;
    pstSetTabActive('pstBtnPartenza', false);
    document.getElementById('pstMapStatus').textContent = '';
    pstRenderCanvasImmagine();
  } else if (pstMapArmaArrivo) {
    pstMappaData.arrivo_x = xPct; pstMappaData.arrivo_y = yPct;
    pstUpsertMappa({ arrivo_x: xPct, arrivo_y: yPct });
    pstMapArmaArrivo = false;
    pstSetTabActive('pstBtnArrivo', false);
    document.getElementById('pstMapStatus').textContent = '';
    pstRenderCanvasImmagine();
  } else if (pstMapArmedPostazioneId) {
    pstSalvaPinImmagine(pstMapArmedPostazioneId, xPct, yPct);
  }
}

function pstToggleArmaPartenza() {
  pstMapArmaPartenza = !pstMapArmaPartenza;
  pstMapArmaArrivo = false;
  pstMapModalitaDisegno = false;
  pstMapArmedPostazioneId = null;
  pstSetTabActive('pstBtnPartenza', pstMapArmaPartenza);
  pstSetTabActive('pstBtnArrivo', false);
  document.getElementById('pstBtnDisegnaPercorso').textContent = '✏️ Disegna percorso';
  document.getElementById('pstMapStatus').textContent = pstMapArmaPartenza ? 'Clicca sulla mappa per indicare la partenza.' : '';
}

function pstToggleArmaArrivo() {
  pstMapArmaArrivo = !pstMapArmaArrivo;
  pstMapArmaPartenza = false;
  pstMapModalitaDisegno = false;
  pstMapArmedPostazioneId = null;
  pstSetTabActive('pstBtnArrivo', pstMapArmaArrivo);
  pstSetTabActive('pstBtnPartenza', false);
  document.getElementById('pstBtnDisegnaPercorso').textContent = '✏️ Disegna percorso';
  document.getElementById('pstMapStatus').textContent = pstMapArmaArrivo ? 'Clicca sulla mappa per indicare l\'arrivo.' : '';
}

function pstZoomImmagine(direzione) {
  pstImgZoom = Math.max(0.5, Math.min(4, Math.round((pstImgZoom + direzione * 0.25) * 100) / 100));
  document.getElementById('pstMapZoomWrap').style.transform = 'scale(' + pstImgZoom + ')';
  document.getElementById('pstMapZoomLabel').textContent = Math.round(pstImgZoom * 100) + '%';
}

function pstZoomImmagineReset() {
  pstImgZoom = 1;
  document.getElementById('pstMapZoomWrap').style.transform = 'scale(1)';
  document.getElementById('pstMapZoomLabel').textContent = '100%';
}

function pstAnteprimaSpessorePercorso(valore) {
  const spessore = valore * 0.1;
  if (pstMappaData.tipo === 'google') return; // il google mode aggiorna solo al rilascio
  const svg = document.getElementById('pstMapSvg');
  if (!svg) return;
  const linea = svg.querySelector('polyline');
  if (linea) linea.setAttribute('stroke-width', spessore);
  svg.querySelectorAll('circle').forEach(c => c.setAttribute('r', spessore * 0.8));
}

async function pstSalvaSpessorePercorso(valore) {
  pstMappaData.route_thickness = parseInt(valore, 10);
  await pstUpsertMappa({ route_thickness: pstMappaData.route_thickness });
  if (pstMappaData.tipo === 'google') pstDisegnaPercorsoGoogle();
}

// Disegna il pin di una postazione sul canvas. ricco=true mostra indirizzo/mezzo/volontari (per le mappe singole).
function _pstDisegnaPinCanvas(ctx, cv, p, ricco) {
  const radioById = {}; (tlcData||[]).forEach(t => radioById[t.id] = t);
  const mezzoById = {}; (mezziData||[]).forEach(m => mezzoById[m.id] = m);
  const iconTr = { mezzo_fisso: '🚗', trasportato: '🚐', piedi: '🚶' };

  const px = p.map_x / 100 * cv.width, py = p.map_y / 100 * cv.height;
  const dx = ((p.label_dx != null ? p.label_dx : 10) / PST_IMG_BASE_WIDTH) * cv.width;
  const dy = ((p.label_dy != null ? p.label_dy : -40) / PST_IMG_BASE_WIDTH) * cv.width;
  const lx = px + dx, ly = py + dy;
  const haVol = p.volontari.length > 0, haVigile = !!p.vigile_presente;
  let bordo = '#999';
  if (haVigile && haVol) bordo = '#16a34a';
  else if (haVigile) bordo = '#06b6d4';
  else if (haVol) bordo = '#16a34a';

  ctx.strokeStyle = '#333'; ctx.lineWidth = cv.width * 0.0015;
  ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(lx, ly); ctx.stroke();
  ctx.fillStyle = '#333';
  ctx.beginPath(); ctx.arc(px, py, cv.width * 0.003, 0, Math.PI * 2); ctx.fill();

  const fontBase = Math.round(cv.width * (ricco ? 0.012 : 0.014));
  const righe = [];
  righe.push({ testo: p.numero || ('#' + p.id), bold: true, size: fontBase * (ricco ? 1.15 : 1) });
  if (ricco) {
    if (p.indirizzo) righe.push({ testo: p.indirizzo, bold: false, size: fontBase * 0.9, colore: '#444' });
    const mezzoTxt = p.mezzo_id && mezzoById[p.mezzo_id] ? _pstLabelMezzo(mezzoById[p.mezzo_id]) : null;
    if (mezzoTxt) righe.push({ testo: '🚛 ' + mezzoTxt, bold: false, size: fontBase * 0.9 });
    if (p.volontari.length) {
      p.volontari.forEach(a => { const v = a.volontari || {}; righe.push({ testo: iconTr[a.trasporto||'piedi'] + ' ' + (v.cognome||'') + ' ' + (v.nome||''), bold: false, size: fontBase * 0.9 }); });
    } else {
      righe.push({ testo: 'nessuno', bold: false, size: fontBase * 0.9, colore: '#999' });
    }
  }

  let maxW = 0;
  righe.forEach(r => { ctx.font = (r.bold ? 'bold ' : '') + Math.round(r.size) + 'px sans-serif'; maxW = Math.max(maxW, ctx.measureText(r.testo).width); });
  const padX = cv.width * 0.006, padY = cv.width * 0.005;
  const lineH = fontBase * 1.35;
  const boxW = maxW + padX * 2;
  const boxH = righe.length * lineH + padY * 2;

  if (p.assegnata_ana === false) ctx.globalAlpha = 0.6;
  ctx.fillStyle = '#fff';
  ctx.fillRect(lx, ly - boxH, boxW, boxH);
  ctx.strokeStyle = bordo; ctx.lineWidth = cv.width * 0.0018;
  if (!haVigile && !haVol) ctx.setLineDash([cv.width * 0.004, cv.width * 0.004]);
  ctx.strokeRect(lx, ly - boxH, boxW, boxH);
  ctx.setLineDash([]);
  if (haVigile && haVol) { ctx.strokeStyle = '#06b6d4'; ctx.strokeRect(lx - cv.width * 0.0025, ly - boxH - cv.width * 0.0025, boxW + cv.width * 0.005, boxH + cv.width * 0.005); }

  ctx.textBaseline = 'alphabetic';
  let ty = ly - boxH + padY + fontBase;
  righe.forEach(r => {
    ctx.font = (r.bold ? 'bold ' : '') + Math.round(r.size) + 'px sans-serif';
    ctx.fillStyle = r.colore || '#111';
    ctx.fillText(r.testo, lx + padX, ty);
    ty += lineH;
  });
  ctx.globalAlpha = 1;
}

// Disegna sfondo + percorso + partenza/arrivo su un canvas già dimensionato; ritorna via callback
function _pstDisegnaBaseMappa(cv, ctx, img) {
  ctx.drawImage(img, 0, 0);
  const spessorePx = (pstMappaData.route_thickness || 3) * 0.001 * cv.width;
  const percorso = pstMappaData.percorso || [];
  if (percorso.length > 1) {
    ctx.strokeStyle = '#d92b2b'; ctx.lineWidth = spessorePx;
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.beginPath();
    percorso.forEach((p, i) => {
      const px = p.x / 100 * cv.width, py = p.y / 100 * cv.height;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    });
    ctx.stroke();
  }
  const disegnaBandiera = (bx, by, emoji) => {
    if (bx == null) return;
    const px = bx / 100 * cv.width, py = by / 100 * cv.height;
    ctx.font = Math.round(cv.width * 0.03) + 'px sans-serif';
    ctx.textBaseline = 'bottom';
    ctx.fillText(emoji, px - cv.width * 0.012, py);
  };
  disegnaBandiera(pstMappaData.partenza_x, pstMappaData.partenza_y, '🚩');
  disegnaBandiera(pstMappaData.arrivo_x, pstMappaData.arrivo_y, '🏁');
}

async function pstScaricaMappaImmagine() {
  if (!pstMappaData) return;
  await pstFirmaMappa();
  if (!pstMappaData._img) { alert('File non disponibile.'); return; }
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => {
    try {
    const cv = document.createElement('canvas');
    cv.width = img.naturalWidth;
    cv.height = img.naturalHeight;
    const ctx = cv.getContext('2d');
    _pstDisegnaBaseMappa(cv, ctx, img);

    pstPostazioni.filter(p => p.map_x != null && p.map_y != null).forEach(p => {
      _pstDisegnaPinCanvas(ctx, cv, p, false);
    });

    cv.toBlob(blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const safeName = (pstIntervento.evento || 'evento').replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 40);
      a.href = url; a.download = 'Mappa_' + safeName + '.png';
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 'image/png');
    } catch(err) {
      alert('Impossibile generare il download (limitazione di sicurezza del browser sull\'immagine). Prova a fare uno screenshot della mappa.');
    }
  };
  img.onerror = () => alert('Impossibile scaricare l\'immagine (problema di accesso all\'immagine salvata).');
  img.src = pstMappaData._img;
}

// Scarica una mappa individuale per ogni postazione con assegnata_ana=true e già posizionata,
// mostrando solo il quadrato ricco (indirizzo/mezzo/volontari) di quella postazione.
async function pstScaricaMappeIndividuali() {
  await pstFirmaMappa();
  if (!pstMappaData || !pstMappaData._img) { alert('Serve una mappa a immagine per questa funzione.'); return; }
  const target = pstPostazioni.filter(p => p.assegnata_ana !== false && p.map_x != null && p.map_y != null);
  if (!target.length) { alert('Nessuna postazione ANA posizionata sulla mappa.'); return; }
  if (!confirm('Scaricare ' + target.length + ' mappe (una per postazione ANA)?')) return;

  const img = await new Promise((resolve, reject) => {
    const im = new Image(); im.crossOrigin = 'anonymous';
    im.onload = () => resolve(im);
    im.onerror = () => reject(new Error('Impossibile caricare l\'immagine mappa.'));
    im.src = pstMappaData._img;
  }).catch(e => { alert(e.message); return null; });
  if (!img) return;

  for (let i = 0; i < target.length; i++) {
    const p = target[i];
    const cv = document.createElement('canvas');
    cv.width = img.naturalWidth; cv.height = img.naturalHeight;
    const ctx = cv.getContext('2d');
    _pstDisegnaBaseMappa(cv, ctx, img);
    _pstDisegnaPinCanvas(ctx, cv, p, true);

    await new Promise(resolve => {
      cv.toBlob(blob => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        const safeNum = (p.numero || p.indirizzo || ('postazione' + p.id)).replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 30);
        a.href = url; a.download = 'Mappa_' + safeNum + '.png';
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout(() => { URL.revokeObjectURL(url); resolve(); }, 300);
      }, 'image/png');
    });
  }
}

async function pstSalvaPinImmagine(postazioneId, xPct, yPct) {
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + postazioneId, {
      method: 'PATCH', headers: HJ,
      body: JSON.stringify({ map_x: xPct, map_y: yPct })
    });
    const p = pstPostazioni.find(x => x.id === postazioneId);
    if (p) { p.map_x = xPct; p.map_y = yPct; }
    pstMapArmedPostazioneId = null;
    document.getElementById('pstMapStatus').textContent = '';
    pstRenderCanvasImmagine();
    pstRenderListePosizionamento();
  } catch(e) { alert('Errore nel posizionamento.'); }
}

function pstCaricaGoogleMapsScript(apiKey) {
  return new Promise((resolve, reject) => {
    if (window.google && window.google.maps) { resolve(); return; }
    const existing = document.getElementById('pstGoogleMapsScript');
    if (existing) { existing.addEventListener('load', () => resolve()); return; }
    const s = document.createElement('script');
    s.id = 'pstGoogleMapsScript';
    s.src = 'https://maps.googleapis.com/maps/api/js?key=' + encodeURIComponent(apiKey);
    s.onload = () => resolve();
    s.onerror = () => reject(new Error('Impossibile caricare Google Maps. Controlla la API key.'));
    document.head.appendChild(s);
  });
}

async function pstRenderCanvasGoogle() {
  const canvas  = document.getElementById('pstMapCanvas');
  const noImg   = document.getElementById('pstMapNessunaImmagine');
  const layout  = document.getElementById('pstMapLayout');
  const toolbar = document.getElementById('pstMapToolbar');
  const zoomCtrl = document.getElementById('pstMapZoomControls');
  const btnScarica = document.getElementById('pstBtnScaricaMappa');
  zoomCtrl.style.display = 'none';
  btnScarica.style.display = 'none';
  document.getElementById('pstBtnScaricaMappeAna').style.display = 'none';

  const apiKey = (document.getElementById('pstMapApiKey').value || localStorage.getItem('pst_gmaps_key') || '').trim();
  if (!apiKey) {
    layout.style.display = 'none'; toolbar.style.display = 'none';
    noImg.style.display = 'block';
    noImg.textContent = 'inserisci la tua Google Maps API Key qui sopra per attivare la mappa.';
    return;
  }
  localStorage.setItem('pst_gmaps_key', apiKey);

  try { await pstCaricaGoogleMapsScript(apiKey); }
  catch(e) { noImg.style.display = 'block'; noImg.textContent = e.message; layout.style.display = 'none'; toolbar.style.display = 'none'; return; }

  noImg.style.display = 'none';
  layout.style.display = 'grid';
  toolbar.style.display = 'flex';
  document.getElementById('pstSpessorePercorso').value = pstMappaData.route_thickness || 3;

  canvas.innerHTML = '';
  const center = { lat: pstMappaData.google_center_lat || 45.1367, lng: pstMappaData.google_center_lng || 8.4519 };
  pstMapGoogleInstance = new google.maps.Map(canvas, { center, zoom: pstMappaData.google_zoom || 15 });

  if (pstMapGoogleClickListener) google.maps.event.removeListener(pstMapGoogleClickListener);
  pstMapGoogleClickListener = pstMapGoogleInstance.addListener('click', (e) => pstGestisciClickGoogle(e));

  pstDisegnaPercorsoGoogle();
  pstDisegnaPinGoogle();
}

function pstDisegnaPercorsoGoogle() {
  if (pstMapGooglePolyline) pstMapGooglePolyline.setMap(null);
  const percorso = pstMappaData.percorso || [];
  pstMapGooglePolyline = new google.maps.Polyline({
    path: percorso.map(p => ({ lat: p.lat, lng: p.lng })),
    strokeColor: '#d92b2b', strokeWeight: pstMappaData.route_thickness || 3
  });
  pstMapGooglePolyline.setMap(pstMapGoogleInstance);
}

let pstMapGooglePartenzaMarker = null;
let pstMapGoogleArrivoMarker = null;

function pstDisegnaPinGoogle() {
  Object.values(pstMapGoogleMarkers).forEach(m => m.setMap(null));
  pstMapGoogleMarkers = {};
  pstPostazioni.filter(p => p.map_lat != null && p.map_lng != null).forEach(p => {
    const marker = new google.maps.Marker({
      position: { lat: p.map_lat, lng: p.map_lng },
      map: pstMapGoogleInstance,
      label: p.numero || '',
      title: (p.numero || '') + ' ' + (p.indirizzo || '')
    });
    marker.addListener('click', () => {
      if (confirm('Rimuovere questa postazione dalla mappa?')) pstRimuoviDallaMappa(p.id);
    });
    pstMapGoogleMarkers[p.id] = marker;
  });

  if (pstMapGooglePartenzaMarker) pstMapGooglePartenzaMarker.setMap(null);
  if (pstMappaData.partenza_lat != null) {
    pstMapGooglePartenzaMarker = new google.maps.Marker({
      position: { lat: pstMappaData.partenza_lat, lng: pstMappaData.partenza_lng },
      map: pstMapGoogleInstance, label: '🚩', title: 'Partenza'
    });
  }
  if (pstMapGoogleArrivoMarker) pstMapGoogleArrivoMarker.setMap(null);
  if (pstMappaData.arrivo_lat != null) {
    pstMapGoogleArrivoMarker = new google.maps.Marker({
      position: { lat: pstMappaData.arrivo_lat, lng: pstMappaData.arrivo_lng },
      map: pstMapGoogleInstance, label: '🏁', title: 'Arrivo'
    });
  }
}

function pstGestisciClickGoogle(e) {
  const lat = e.latLng.lat(), lng = e.latLng.lng();
  if (pstMapModalitaDisegno) {
    const percorso = (pstMappaData.percorso || []).slice();
    percorso.push({ lat, lng });
    pstMappaData.percorso = percorso;
    pstUpsertMappa({ percorso: percorso });
    pstDisegnaPercorsoGoogle();
  } else if (pstMapArmaPartenza) {
    pstMappaData.partenza_lat = lat; pstMappaData.partenza_lng = lng;
    pstUpsertMappa({ partenza_lat: lat, partenza_lng: lng });
    pstMapArmaPartenza = false;
    pstSetTabActive('pstBtnPartenza', false);
    document.getElementById('pstMapStatus').textContent = '';
    pstDisegnaPinGoogle();
  } else if (pstMapArmaArrivo) {
    pstMappaData.arrivo_lat = lat; pstMappaData.arrivo_lng = lng;
    pstUpsertMappa({ arrivo_lat: lat, arrivo_lng: lng });
    pstMapArmaArrivo = false;
    pstSetTabActive('pstBtnArrivo', false);
    document.getElementById('pstMapStatus').textContent = '';
    pstDisegnaPinGoogle();
  } else if (pstMapArmedPostazioneId) {
    pstSalvaPinGoogle(pstMapArmedPostazioneId, lat, lng);
  }
}

async function pstSalvaPinGoogle(postazioneId, lat, lng) {
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + postazioneId, {
      method: 'PATCH', headers: HJ,
      body: JSON.stringify({ map_lat: lat, map_lng: lng })
    });
    const p = pstPostazioni.find(x => x.id === postazioneId);
    if (p) { p.map_lat = lat; p.map_lng = lng; }
    pstMapArmedPostazioneId = null;
    document.getElementById('pstMapStatus').textContent = '';
    pstDisegnaPinGoogle();
    pstRenderListePosizionamento();
  } catch(e) { alert('Errore nel posizionamento.'); }
}

async function pstCentraGoogleMap() {
  const apiKey = (document.getElementById('pstMapApiKey').value || '').trim();
  const indirizzo = (document.getElementById('pstMapIndirizzoCentro').value || '').trim();
  if (!apiKey || !indirizzo) { alert('Inserisci API key e indirizzo.'); return; }
  try {
    const res = await fetch('https://maps.googleapis.com/maps/api/geocode/json?address=' + encodeURIComponent(indirizzo) + '&key=' + encodeURIComponent(apiKey));
    const data = await res.json();
    if (!data.results || !data.results.length) { alert('Indirizzo non trovato.'); return; }
    const loc = data.results[0].geometry.location;
    await pstUpsertMappa({ google_center_lat: loc.lat, google_center_lng: loc.lng });
    if (pstMapGoogleInstance) pstMapGoogleInstance.setCenter(loc);
  } catch(e) { alert('Errore nella ricerca dell\'indirizzo.'); }
}

function pstToggleDisegnoPercorso() {
  pstMapModalitaDisegno = !pstMapModalitaDisegno;
  pstMapArmedPostazioneId = null;
  pstMapArmaPartenza = false;
  pstMapArmaArrivo = false;
  pstSetTabActive('pstBtnPartenza', false);
  pstSetTabActive('pstBtnArrivo', false);
  const btn = document.getElementById('pstBtnDisegnaPercorso');
  const status = document.getElementById('pstMapStatus');
  if (pstMapModalitaDisegno) {
    btn.textContent = '✔ Fine disegno';
    status.textContent = 'Clicca sulla mappa per aggiungere punti al percorso.';
  } else {
    btn.textContent = '✏️ Disegna percorso';
    status.textContent = '';
  }
}

async function pstCancellaPercorso() {
  if (!confirm('Cancellare il percorso disegnato?')) return;
  pstMappaData.percorso = [];
  await pstUpsertMappa({ percorso: [] });
  if (pstMappaData.tipo === 'google') pstDisegnaPercorsoGoogle(); else pstRenderCanvasImmagine();
}

function pstArmaPosizionamento(postazioneId) {
  pstMapModalitaDisegno = false;
  pstMapArmaPartenza = false;
  pstMapArmaArrivo = false;
  pstSetTabActive('pstBtnPartenza', false);
  pstSetTabActive('pstBtnArrivo', false);
  document.getElementById('pstBtnDisegnaPercorso').textContent = '✏️ Disegna percorso';
  pstMapArmedPostazioneId = postazioneId;
  const p = pstPostazioni.find(x => x.id === postazioneId);
  document.getElementById('pstMapStatus').textContent = 'Clicca sulla mappa per posizionare: ' + (p ? (p.numero || p.indirizzo) : '');
  pstRenderListePosizionamento();
}

async function pstRimuoviDallaMappa(postazioneId) {
  try {
    await sbFetch(SUPA_URL + '/rest/v1/postazioni?id=eq.' + postazioneId, {
      method: 'PATCH', headers: HJ,
      body: JSON.stringify({ map_x: null, map_y: null, map_lat: null, map_lng: null })
    });
    const p = pstPostazioni.find(x => x.id === postazioneId);
    if (p) { p.map_x = null; p.map_y = null; p.map_lat = null; p.map_lng = null; }
    if (pstMappaData.tipo === 'google') pstDisegnaPinGoogle(); else pstRenderCanvasImmagine();
    pstRenderListePosizionamento();
  } catch(e) { alert('Errore.'); }
}

function pstRenderListePosizionamento() {
  const boxDa = document.getElementById('pstMapDaPosizionare');
  const boxOk = document.getElementById('pstMapPosizionate');
  if (!boxDa || !boxOk) return;
  const tipo = pstMappaData ? pstMappaData.tipo : 'immagine';
  const isPosizionata = (p) => tipo === 'google' ? (p.map_lat != null && p.map_lng != null) : (p.map_x != null && p.map_y != null);

  const daPosizionare = pstPostazioni.filter(p => !isPosizionata(p));
  const posizionate = pstPostazioni.filter(isPosizionata);

  boxDa.innerHTML = daPosizionare.length ? daPosizionare.map(p => {
    const attivo = pstMapArmedPostazioneId === p.id;
    return '<button class="chip' + (attivo ? ' on' : '') + '" onclick="pstArmaPosizionamento(' + p.id + ')">📍 ' + (p.numero ? p.numero + ' — ' : '') + (p.indirizzo || 'senza indirizzo') + '</button>';
  }).join('') : '<div class="loading-msg sm">tutte posizionate</div>';

  boxOk.innerHTML = posizionate.length ? posizionate.map(p => {
    return '<div class="pst-posizionata">'
      + '<span>' + (p.numero ? p.numero + ' — ' : '') + (p.indirizzo || '—') + '</span>'
      + '<button class="btn sm danger" aria-label="Togli dalla mappa" onclick="pstRimuoviDallaMappa(' + p.id + ')">✕</button>'
      + '</div>';
  }).join('') : '<div class="loading-msg sm">nessuna postazione sulla mappa</div>';
}

// -- DB AVANZATO (Supabase) --

