const GOOGLE_API_KEY    = 'AIzaSyAWKS-pik6t_YD6CReijjsgBEzj-qKReUg';
const GALLERIA_FOLDER_ID = '1Ef-5hijyauKAuASNXPBSCmVJCbEExnP1';

let galleriaAlbumsCache = null;   // cache album
let galleriaCurrentAlbum = null;  // album aperto al momento
let galleriaCurrentPhotos = [];   // foto dell'album corrente
let galleriaLightboxIdx = 0;

async function caricaGalleria() {
  const content = document.getElementById('gallContent');
  const back    = document.getElementById('gallBackBtn');
  if (!content) return;
  back.style.display = 'none';
  galleriaCurrentAlbum = null;
  document.getElementById('gallTitle').textContent = 'Galleria';
  document.getElementById('gallSub').textContent = 'Album fotografici degli eventi';

  if (GOOGLE_API_KEY === 'INCOLLA_QUI_LA_TUA_CHIAVE_API' || !GOOGLE_API_KEY) {
    content.innerHTML = '<div class="loading-msg">⚠️ Chiave API Google non configurata. Inserisci la chiave in area-riservata.js.</div>';
    return;
  }

  if (galleriaAlbumsCache) {
    renderAlbums(galleriaAlbumsCache);
    return;
  }

  content.innerHTML = '<div class="loading-msg">Caricamento album…</div>';
  try {
    // Lista sottocartelle (album) nella cartella principale
    const q = "'" + GALLERIA_FOLDER_ID + "' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false";
    const url = 'https://www.googleapis.com/drive/v3/files'
      + '?q=' + encodeURIComponent(q)
      + '&fields=' + encodeURIComponent('files(id,name,modifiedTime)')
      + '&orderBy=name desc'
      + '&pageSize=100'
      + '&supportsAllDrives=true&includeItemsFromAllDrives=true'
      + '&key=' + GOOGLE_API_KEY;
    const res = await fetch(url);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error((err.error && err.error.message) || 'errore API');
    }
    const data = await res.json();
    const albums = data.files || [];

    // Per ogni album cerco una copertina (prima foto)
    const albumsConCover = await Promise.all(albums.map(async (alb) => {
      try {
        const cq = "'" + alb.id + "' in parents and (mimeType contains 'image/') and trashed = false";
        const cu = 'https://www.googleapis.com/drive/v3/files'
          + '?q=' + encodeURIComponent(cq)
          + '&fields=files(id,thumbnailLink)'
          + '&pageSize=1'
          + '&supportsAllDrives=true&includeItemsFromAllDrives=true'
          + '&key=' + GOOGLE_API_KEY;
        const cr = await fetch(cu);
        const cd = await cr.json();
        const cover = cd.files && cd.files[0];
        return Object.assign({}, alb, { coverId: cover ? cover.id : null });
      } catch(e) {
        return alb;
      }
    }));

    galleriaAlbumsCache = albumsConCover;
    renderAlbums(albumsConCover);
  } catch(e) {
    content.innerHTML = '<div class="loading-msg bad">errore: ' + (e.message || 'caricamento fallito') + '</div>';
  }
}

function renderAlbums(albums) {
  const content = document.getElementById('gallContent');
  if (!albums.length) {
    content.innerHTML = '<div class="empty">Nessun album trovato. Crea sottocartelle nella cartella Drive principale.</div>';
    return;
  }
  let html = '<div class="gall-albums">';
  albums.forEach(alb => {
    const dateStr = alb.modifiedTime ? new Date(alb.modifiedTime).toLocaleDateString('it-IT', {month:'short', year:'numeric'}) : '';
    const cover = alb.coverId
      ? '<img src="https://lh3.googleusercontent.com/d/' + alb.coverId + '=w600" loading="lazy" onerror="this.style.display=\'none\';this.parentNode.innerHTML=\'<span class=&quot;gall-folder-icon&quot;>📁</span>\'">'
      : '<span class="gall-folder-icon">📁</span>';
    html += '<div class="card gall-album" onclick="apriAlbum(\'' + alb.id + '\', \'' + alb.name.replace(/'/g, "\\'") + '\')">'
      + '<div class="gall-album-cover">' + cover + '</div>'
      + '<b class="gall-album-name">' + alb.name + '</b>'
      + (dateStr ? '<span class="sub">' + dateStr + '</span>' : '')
      + '</div>';
  });
  html += '</div>';
  content.innerHTML = html;
}

async function apriAlbum(folderId, nome) {
  const content = document.getElementById('gallContent');
  document.getElementById('gallBackBtn').style.display = 'inline-block';
  document.getElementById('gallTitle').textContent = nome;
  document.getElementById('gallSub').textContent = 'caricamento foto...';
  galleriaCurrentAlbum = folderId;
  content.innerHTML = '<div class="loading-msg">caricamento foto...</div>';

  try {
    const q = "'" + folderId + "' in parents and (mimeType contains 'image/') and trashed = false";
    let allFiles = [];
    let pageToken = null;

    do {
      let url = 'https://www.googleapis.com/drive/v3/files'
        + '?q=' + encodeURIComponent(q)
        + '&fields=' + encodeURIComponent('nextPageToken,files(id,name,thumbnailLink,imageMediaMetadata)')
        + '&orderBy=name'
        + '&pageSize=1000'
        + '&supportsAllDrives=true&includeItemsFromAllDrives=true'
        + '&key=' + GOOGLE_API_KEY;
      if (pageToken) url += '&pageToken=' + encodeURIComponent(pageToken);

      const res = await fetch(url);
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error((err.error && err.error.message) || 'errore API');
      }
      const data = await res.json();
      allFiles = allFiles.concat(data.files || []);
      pageToken = data.nextPageToken || null;

      // aggiorna contatore progressivo durante il caricamento
      document.getElementById('gallSub').textContent = allFiles.length + ' foto (caricamento...)';
    } while (pageToken);

    galleriaCurrentPhotos = allFiles;
    document.getElementById('gallSub').textContent = galleriaCurrentPhotos.length + ' foto';

    if (!galleriaCurrentPhotos.length) {
      content.innerHTML = '<div class="loading-msg">album vuoto.</div>';
      return;
    }

    let html = '<div class="gall-photos">';
    galleriaCurrentPhotos.forEach((f, i) => {
      const thumb = 'https://lh3.googleusercontent.com/d/' + f.id + '=w400';
      html += '<div class="gall-photo" onclick="apriLightbox(' + i + ')">'
        + '<img src="' + thumb + '" loading="lazy" alt="' + (f.name || '') + '">'
        + '</div>';
    });
    html += '</div>';
    content.innerHTML = html;
  } catch(e) {
    content.innerHTML = '<div class="loading-msg bad">errore: ' + (e.message || 'caricamento fallito') + '</div>';
  }
}

function galleriaBack() {
  caricaGalleria();
}

function apriLightbox(idx) {
  if (!galleriaCurrentPhotos.length) return;
  galleriaLightboxIdx = idx;
  mostraFotoLightbox();
  document.getElementById('gallLightbox').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function mostraFotoLightbox() {
  const f = galleriaCurrentPhotos[galleriaLightboxIdx];
  if (!f) return;
  document.getElementById('gallLightboxImg').src = 'https://lh3.googleusercontent.com/d/' + f.id + '=w1920';
  document.getElementById('gallLightboxCap').textContent = (galleriaLightboxIdx + 1) + ' / ' + galleriaCurrentPhotos.length;
}

function lightboxNav(delta, evt) {
  if (evt) evt.stopPropagation();
  const n = galleriaCurrentPhotos.length;
  galleriaLightboxIdx = (galleriaLightboxIdx + delta + n) % n;
  mostraFotoLightbox();
}

function chiudiLightbox(evt, forza) {
  if (!forza && evt && evt.target.id !== 'gallLightbox') return;
  document.getElementById('gallLightbox').classList.remove('open');
  document.body.style.overflow = '';
}

// Frecce tastiera per il lightbox
document.addEventListener('keydown', function(e) {
  const lb = document.getElementById('gallLightbox');
  if (!lb || !lb.classList.contains('open')) return;
  if (e.key === 'ArrowLeft')  lightboxNav(-1);
  if (e.key === 'ArrowRight') lightboxNav(1);
  if (e.key === 'Escape')     chiudiLightbox(null, true);
});

// -- VISITE MEDICHE --
function visitaStatoNorm(v) { return (v.stato_visita || '').replace(' ', '_'); }

const VISITA_STATI = {
  'ESONERO':    { label: 'Esonero',    cls: 'vs-esonero' },
  'DA_FARE':    { label: 'Da Fare',    cls: 'vs-da_fare' },
  'VERIFICA':   { label: 'Verifica',   cls: 'vs-verifica' },
  'SOLO_ESAMI': { label: 'Solo Esami', cls: 'vs-solo_esami' },
  'COMPLETATA': { label: 'Completata', cls: 'vs-completata' }
};

function apriExportVisite() {
  document.getElementById('vexpTestoCorrente').textContent = document.getElementById('volSearch').value || '(vuoto)';
  document.getElementById('visiteExportErr').textContent = '';
  document.getElementById('visiteExportOverlay').classList.add('open');
}

function chiudiExportVisite() {
  document.getElementById('visiteExportOverlay').classList.remove('open');
}

function generaExportVisitePDF() {
  const statiSel = Array.from(document.querySelectorAll('.vexp-stato:checked')).map(c => c.value);
  const colSel = Array.from(document.querySelectorAll('.vexp-col:checked')).map(c => c.value);
  const dataDa = document.getElementById('vexpDataDa').value;
  const dataA = document.getElementById('vexpDataA').value;
  const usaTesto = document.getElementById('vexpSoloTestoRicerca').checked;
  const testo = usaTesto ? document.getElementById('volSearch').value.toLowerCase() : '';

  let dati = volontariData.filter(v => {
    if (v.stato === 'DIMESSO') return false;
    if (!statiSel.includes(visitaStatoNorm(v) || 'VUOTO')) return false;
    if (dataDa && (!v.data_visita || v.data_visita < dataDa)) return false;
    if (dataA && (!v.data_visita || v.data_visita > dataA)) return false;
    if (usaTesto && testo) {
      const hay = ((v.cognome || '') + ' ' + (v.nome || '') + ' ' + (v.codice_fiscale || '')).toLowerCase();
      if (!hay.includes(testo)) return false;
    }
    return true;
  });

  if (dati.length === 0) {
    document.getElementById('visiteExportErr').textContent = 'Nessun risultato con questi filtri.';
    return;
  }

  const colonne = [];
  if (colSel.includes('nome')) colonne.push('Nominativo');
  if (colSel.includes('cf')) colonne.push('Codice Fiscale');
  if (colSel.includes('stato')) colonne.push('Stato');
  if (colSel.includes('data')) colonne.push('Data');

  const righe = dati.map(v => {
    const statoInfo = VISITA_STATI[visitaStatoNorm(v)];
    const r = [];
    if (colSel.includes('nome')) r.push(((v.cognome || '') + ' ' + (v.nome || '')).trim());
    if (colSel.includes('cf')) r.push(v.codice_fiscale || '—');
    if (colSel.includes('stato')) r.push(statoInfo ? statoInfo.label : 'Non impostato');
    if (colSel.includes('data')) r.push(v.data_visita ? new Date(v.data_visita).toLocaleDateString('it-IT') : '—');
    return r;
  });

  const doc = new jspdf.jsPDF();
  doc.setFontSize(14);
  doc.text('Visite Mediche — PC ANA Casale', 14, 16);
  doc.setFontSize(9);
  doc.text('Generato il ' + new Date().toLocaleDateString('it-IT') + ' — ' + dati.length + ' risultati', 14, 22);
  doc.autoTable({
    startY: 28,
    head: [colonne],
    body: righe,
    styles: { fontSize: 8 },
    headStyles: { fillColor: [26, 122, 74] }
  });
  doc.save('visite-mediche-export.pdf');
  chiudiExportVisite();
}

var mezzoDocLoaded = false;

function toggleMezzoDoc(mezzoId) {
  var body = document.getElementById('mezzoDocBody');
  if (!body) return;
  if (body.style.display !== 'none') { body.style.display = 'none'; return; }
  body.style.display = 'block';
  caricaDocMezzo(mezzoId);
}

async function caricaDocMezzo(mezzoId) {
  var body  = document.getElementById('mezzoDocBody');
  var count = document.getElementById('mezzoDocCount');
  if (!body) return;
  body.style.display = 'block';
  try {
    var res  = await sbFetch(SUPA_URL + '/rest/v1/documenti_mezzi?mezzo_id=eq.' + mezzoId + '&select=*&order=data_carico.desc', { headers: H });
    sbOk(res);
    var docs = await res.json();
    await sbFirmaRighe(docs, 'url');
    if (count) count.textContent = '(' + docs.length + ')';

    var DOC_MEZZO_LABEL = {
      'FOTO':'📷 Foto', 'LIBRETTO':'📋 Libretto', 'ASSICURAZIONE':'📄 Assicurazione',
      'REVISIONE':'🔧 Revisione', 'COLLAUDO':'📋 Collaudo', 'ALTRO':'📄 Altro'
    };

    var html = '';
    if (docs.length) {
      html += '<div class="doc-list">';
      docs.forEach(function(d) {
        var label = DOC_MEZZO_LABEL[d.tipo] || d.tipo;
        var data  = d.data_carico ? new Date(d.data_carico).toLocaleDateString('it-IT') : '—';
        html += '<div class="doc-item">'
          + '<span class="doc-item-icon">' + label.split(' ')[0] + '</span>'
          + '<div class="doc-item-info">'
          + '<div class="doc-item-name">' + d.nome_file + '</div>'
          + '<div class="doc-item-meta">' + label.replace(/^[^ ]+ /,'') + ' | ' + data + '</div>'
          + '</div>'
          + '<div class="doc-item-actions">'
          + sbLinkFile(d.url, d._file)
          + '<button class="btn sm danger" aria-label="Elimina" onclick="eliminaDocMezzo(' + d.id + ',' + mezzoId + ')">✕</button>'
          + '</div></div>';
      });
      html += '</div>';
    }
    html += '<button class="doc-add-btn" onclick="apriUploadDocMezzo(' + mezzoId + ')">+ Aggiungi documento</button>';
    body.innerHTML = html;
  } catch(e) {
    body.innerHTML = '<p class="bad">Non disponibile.</p>';
  }
}

async function eliminaDocMezzo(docId, mezzoId) {
  if (!confirm('Eliminare questo documento?')) return;
  await sbFetch(SUPA_URL + '/rest/v1/documenti_mezzi?id=eq.' + docId, { method:'DELETE', headers: H });
  await logAttivita('ha eliminato documento mezzo');
  caricaDocMezzo(mezzoId);
}

var mezzoUploadId = null;
var mezzoUploadFile = null;

function apriUploadDocMezzo(mezzoId) {
  mezzoUploadId   = mezzoId;
  mezzoUploadFile = null;
  var m = mezziData.find(function(x){ return x.id === mezzoId; });
  document.getElementById('mezzoUploadTitle').textContent = 'Carica documento — ' + (m ? m.automezzo : '');
  document.getElementById('mezzoUploadErr').style.display = 'none';
  document.getElementById('mezzoDropText').innerHTML = 'PDF, JPG o PNG — max 10MB';
  document.getElementById('mezzoFileInput').value = '';
  document.getElementById('mezzoUploadOverlay').classList.add('open');
}

function chiudiUploadDocMezzo() {
  document.getElementById('mezzoUploadOverlay').classList.remove('open');
}

function mezzoFileSelected(input) {
  var file = input.files[0];
  if (!file) return;
  if (file.size > 10*1024*1024) {
    document.getElementById('mezzoUploadErr').textContent = 'File troppo grande (max 10MB).';
    document.getElementById('mezzoUploadErr').style.display = 'block';
    return;
  }
  mezzoUploadFile = file;
  var txt = document.getElementById('mezzoDropText');
  if (txt) txt.textContent = '✓ ' + file.name + ' (' + (file.size/1024).toFixed(0) + ' KB)';
}

async function eseguiUploadDocMezzo() {
  if (!mezzoUploadFile || !mezzoUploadId) {
    document.getElementById('mezzoUploadErr').textContent = 'Seleziona un file.';
    document.getElementById('mezzoUploadErr').style.display = 'block';
    return;
  }
  var tipo    = document.getElementById('mezzoDocTipo').value;
  var nomeDoc = document.getElementById('mezzoDocNome').value.trim() || mezzoUploadFile.name;
  var path    = mezzoUploadId + '/' + tipo + '_' + Date.now() + '_' + mezzoUploadFile.name.replace(/[^a-zA-Z0-9._-]/g,'_');
  var errEl   = document.getElementById('mezzoUploadErr');
  var btn     = document.getElementById('mezzoUploadBtn');
  errEl.style.display = 'none';
  btn.disabled = true; btn.textContent = 'caricamento...';
  try {
    var uploadRes = await sbFetch(SUPA_URL + '/storage/v1/object/documenti-mezzi/' + path, {
      method:'POST', headers:{ 'apikey':SUPA_KEY,'Content-Type':mezzoUploadFile.type }, body:mezzoUploadFile
    });
    if (!uploadRes.ok) throw new Error('Errore upload storage');
    var url = sbPercorso('documenti-mezzi', path);

    // Se è foto, aggiorna foto_url nel mezzo
    if (tipo === 'FOTO') {
      await sbFetch(SUPA_URL + '/rest/v1/mezzi?id=eq.' + mezzoUploadId, {
        method:'PATCH', headers:HJ, body:JSON.stringify({ foto_url: url })
      });
    }

    await sbFetch(SUPA_URL + '/rest/v1/documenti_mezzi', {
      method:'POST', headers:Object.assign({},HJ,{'Prefer':'return=minimal'}),
      body:JSON.stringify({ mezzo_id:mezzoUploadId, tipo:tipo, nome_file:nomeDoc, url:url })
    });
    await logAttivita('ha caricato documento mezzo: ' + nomeDoc);
    chiudiUploadDocMezzo();
    caricaDocMezzo(mezzoUploadId);
    caricaMezzi(); // aggiorna galleria con eventuale nuova foto
  } catch(e) { errEl.textContent = 'Errore: ' + e.message; errEl.style.display = 'block'; }
  btn.disabled = false; btn.textContent = 'carica';
}

// -- STATISTICHE --
var statsInterventi = [];
var statsChartTipo  = null;
var statsChartMesi  = null;

async function caricaStatistiche() {
  var anno = document.getElementById('statsAnno').value;
  var url  = SUPA_URL + '/rest/v1/interventi_con_stato?select=*&order=data&stato_calcolato=eq.SVOLTO';
  if (anno) url += '&data=gte.' + anno + '-01-01&data=lte.' + anno + '-12-31';
  var res = await sbFetch(url, { headers: H });
  statsInterventi = await res.json();
  renderStatCards();
  renderChartTipo();
  renderChartMesi(anno);
  renderOreTable();
}

async function initStatistiche() {
  // Popola anni disponibili
  var res   = await sbFetch(SUPA_URL + '/rest/v1/interventi_con_stato?select=data&order=data', { headers: H });
  if (!res.ok) {
    var cards = document.getElementById('statsCards');
    if (cards) cards.innerHTML = '<div class="empty">Non disponibile.</div>';
    return;
  }
  var dati  = await res.json();
  var anni  = [...new Set((dati||[]).map(function(d){ return d.data ? d.data.slice(0,4) : null; }).filter(Boolean))].sort().reverse();
  var sel   = document.getElementById('statsAnno');
  if (!sel) return;
  sel.innerHTML = anni.map(function(a){ return '<option value="'+a+'">'+a+'</option>'; }).join('');
  if (!anni.length) sel.innerHTML = '<option value="">Tutti</option>';
  await caricaStatistiche();
}

function renderStatCards() {
  var el = document.getElementById('statsCards');
  if (!el) return;
  var totInt  = statsInterventi.length;
  var totOre  = statsInterventi.reduce(function(s,i){ return s + parseFloat(i.n_ore||0); }, 0);
  var totVol  = statsInterventi.reduce(function(s,i){ return s + (i.n_volontari||0); }, 0);
  var ic = function(n){ return navIc(n, 22); };
  el.innerHTML = [
    ['Interventi', totInt, 'clock', 'y'],
    ['Ore totali', Math.round(totOre*10)/10, 'clock', 'b'],
    ['Presenze', totVol, 'users', 'y']
  ].map(function(c){
    return '<div class="card stat"><span class="ib ' + c[3] + '">' + ic(c[2]) + '</span><div><b>' + c[1] + '</b><span>' + c[0] + '</span></div></div>';
  }).join('');
}

// Interventi per tipo: righe con barra di avanzamento (componente progbar del riferimento)
function renderChartTipo() {
  var el = document.getElementById('chartStatsTipo');
  if (!el) return;
  var contegg = {};
  statsInterventi.forEach(function(i){
    var t = i.tipo_attivita || 'ALTRO';
    contegg[t] = (contegg[t]||0) + 1;
  });
  var labels = Object.keys(contegg).sort(function(a,b){ return contegg[b] - contegg[a]; });
  if (!labels.length) { el.innerHTML = '<p class="note">Nessun intervento.</p>'; return; }
  var max = Math.max.apply(null, labels.map(function(l){ return contegg[l]; }));
  el.innerHTML = labels.map(function(l){
    return '<div class="stat-row"><span class="lbl">' + l + '</span>'
      + '<div class="progbar"><i style="width:' + Math.round(contegg[l] / max * 100) + '%"></i></div>'
      + '<span class="val">' + contegg[l] + '</span></div>';
  }).join('');
}

// Interventi per mese: colonne del riferimento (.bars), mese corrente in giallo
function renderChartMesi(anno) {
  var el = document.getElementById('chartStatsMesi');
  if (!el) return;
  var mesi   = ['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set','Ott','Nov','Dic'];
  var counts = new Array(12).fill(0);
  statsInterventi.forEach(function(i){
    if (!i.data) return;
    var m = parseInt(i.data.slice(5,7)) - 1;
    if (m >= 0 && m < 12) counts[m]++;
  });
  var top = Math.max.apply(null, counts.concat([1]));
  var oggi = new Date();
  var meseCorr = String(oggi.getFullYear()) === String(anno) ? oggi.getMonth() : -1;
  el.innerHTML = counts.map(function(n, i){
    var h = Math.round(n / top * 130) + 4;
    return '<div class="c"><em>' + n + '</em><i class="' + (i === meseCorr ? 'cur' : '') + '" style="height:' + h + 'px"></i><small>' + mesi[i] + '</small></div>';
  }).join('');
}

function renderOreTable() {
  var el = document.getElementById('statsOreTable');
  if (!el) return;
  // Raccogli ore per volontario dagli ID
  var volMap = {};
  statsInterventi.forEach(function(i){
    var oreT = parseFloat(i.n_ore||0);
    var nVol = (i.volontari_ids||[]).length || i.n_volontari || 1;
    var oreInd = nVol > 0 ? oreT / nVol : oreT;
    (i.volontari_ids||[]).forEach(function(vid){
      if (!volMap[vid]) volMap[vid] = { ore:0, count:0 };
      volMap[vid].ore   += oreInd;
      volMap[vid].count += 1;
    });
  });
  // Carica nomi volontari
  var ids = Object.keys(volMap);
  if (!ids.length) { el.innerHTML = '<div class="empty">Nessun dato.</div>'; return; }
  sbFetch(SUPA_URL + '/rest/v1/volontari?id=in.(' + ids.join(',') + ')&select=id,cognome,nome,codice_fiscale', { headers: H })
    .then(function(r){ return r.json(); })
    .then(function(vols){
      var rows = vols.map(function(v){
        var s = volMap[v.id] || { ore:0, count:0 };
        return { nome: v.cognome + ' ' + v.nome, ore: Math.round(s.ore*10)/10, count: s.count };
      }).sort(function(a,b){ return b.ore - a.ore; });

      var html = '<div class="card tbl stat-ore"><div class="irow ihead"><span>Volontario</span><span class="r">Interventi</span><span class="r">Ore</span></div>';
      rows.forEach(function(r, i){
        html += '<div class="irow"><b>' + (i+1) + '. ' + r.nome + '</b><span class="r">' + r.count + '</span><b class="r">' + r.ore + ' h</b></div>';
      });
      html += '</div>';
      el.innerHTML = html;
    });
}

