async function stampaPDFStatistiche() {
  var anno  = document.getElementById('statsAnno').value || 'tutti gli anni';
  var oggi  = new Date().toLocaleDateString('it-IT', { day:'2-digit', month:'long', year:'numeric' });
  var totInt = statsInterventi.length;
  var totOre = Math.round(statsInterventi.reduce(function(s,i){ return s+parseFloat(i.n_ore||0); },0)*10)/10;
  var totVol = statsInterventi.reduce(function(s,i){ return s+(i.n_volontari||0); },0);

  // Ore per volontario
  var volMap = {};
  statsInterventi.forEach(function(i){
    var oreT = parseFloat(i.n_ore||0);
    var nVol = (i.volontari_ids||[]).length || i.n_volontari || 1;
    var oreInd = nVol > 0 ? oreT / nVol : oreT;
    (i.volontari_ids||[]).forEach(function(vid){
      if (!volMap[vid]) volMap[vid] = { ore:0, count:0 };
      volMap[vid].ore += oreInd; volMap[vid].count++;
    });
  });
  var ids = Object.keys(volMap);
  var vols = ids.length ? await sbFetch(SUPA_URL+'/rest/v1/volontari?id=in.('+ids.join(',')+')&select=id,cognome,nome',{headers:H}).then(function(r){return r.json();}) : [];
  var rows = vols.map(function(v){
    var s = volMap[v.id]||{ore:0,count:0};
    return { nome:v.cognome+' '+v.nome, ore:Math.round(s.ore*10)/10, count:s.count };
  }).sort(function(a,b){ return b.ore-a.ore; });

  // Tipi
  var contegg = {};
  statsInterventi.forEach(function(i){ var t=i.tipo_attivita||'ALTRO'; contegg[t]=(contegg[t]||0)+1; });

  var win = window.open('','_blank');
  win.document.write('<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8">'
    + '<title>Statistiche Interventi ' + anno + '</title>'
    + '<style>body{font-family:Georgia,serif;font-size:10pt;color:#111;margin:2cm}'
    + 'h1{font-size:16pt;font-weight:700;color:#1a7a4a;margin:0 0 0.2rem}'
    + 'h2{font-size:11pt;font-weight:700;margin:1.2rem 0 0.5rem;padding-bottom:0.3rem;border-bottom:2px solid #1a7a4a;color:#1a7a4a}'
    + '.meta{font-size:9pt;color:#666;margin-bottom:1.2rem}'
    + '.stats{display:flex;gap:1rem;margin-bottom:1.2rem}'
    + '.stat{background:#f3f4f6;border-radius:8px;padding:0.6rem 1rem;text-align:center;flex:1}'
    + '.stat-num{font-size:1.4rem;font-weight:700;line-height:1}'
    + '.stat-lbl{font-size:8pt;color:#666;text-transform:uppercase}'
    + 'table{width:100%;border-collapse:collapse;font-size:9pt}'
    + 'th{text-align:left;padding:5px 8px;background:#1a7a4a;color:white;font-weight:700}'
    + 'td{padding:5px 8px;border-bottom:0.5px solid #e5e7eb}'
    + 'tr:nth-child(even) td{background:#f9fafb}'
    + '@media print{body{margin:1.5cm}.stat{-webkit-print-color-adjust:exact;print-color-adjust:exact}th{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'
    + '</style></head><body>'
    + _headerHtmlCartaIntestata()
    + '<h1 style="font-size:13pt">Statistiche Interventi</h1>'
    + '<div class="meta">Anno: ' + anno + ' &nbsp;|&nbsp; Generato il ' + oggi + '</div>'
    + '<div class="stats">'
    + '<div class="stat"><div class="stat-num" style="color:#1a7a4a">'+totInt+'</div><div class="stat-lbl">Interventi</div></div>'
    + '<div class="stat"><div class="stat-num" style="color:#185fa5">'+totOre+'h</div><div class="stat-lbl">Ore totali</div></div>'
    + '<div class="stat"><div class="stat-num" style="color:#854f0b">'+totVol+'</div><div class="stat-lbl">Presenze</div></div>'
    + '</div>'
    + '<h2>Interventi per tipo</h2>'
    + '<table><thead><tr><th>Tipo attività</th><th style="text-align:right">N° interventi</th></tr></thead><tbody>'
    + Object.entries(contegg).sort(function(a,b){return b[1]-a[1];}).map(function(e,i){
        return '<tr><td>'+(i+1)+'. '+e[0]+'</td><td style="text-align:right">'+e[1]+'</td></tr>';
      }).join('')
    + '</tbody></table>'
    + '<h2>Ore per volontario</h2>'
    + '<table><thead><tr><th>Volontario</th><th style="text-align:right">Interventi</th><th style="text-align:right">Ore totali</th></tr></thead><tbody>'
    + rows.map(function(r,i){
        return '<tr><td>'+(i+1)+'. '+r.nome+'</td><td style="text-align:right">'+r.count+'</td><td style="text-align:right;font-weight:700;color:#1a7a4a">'+r.ore+'h</td></tr>';
      }).join('')
    + '</tbody></table>'
    + '<script>window.onload=function(){setTimeout(function(){window.print();},400);}<\/script>'
    + '</body></html>');
  win.document.close();
}

// -- EXPORT MODULO TERRITORIALE (Excel) --
// Template embeddato (formato ANA)
const MODULO_TERRITORIALE_B64 = '';

function caricaExcelJS() {
  return new Promise(function(resolve, reject) {
    if (window.ExcelJS) { resolve(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.4.0/exceljs.min.js';
    s.onload = function() { resolve(); };
    s.onerror = function() { reject(new Error('exceljs load failed')); };
    document.head.appendChild(s);
  });
}

function _b64ToArrayBuffer(b64) {
  var bin = atob(b64);
  var len = bin.length;
  var bytes = new Uint8Array(len);
  for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

async function esportaModuloTerritoriale(id) {
  try {
    await caricaExcelJS();
  } catch(e) { alert('Impossibile caricare la libreria Excel.'); return; }

  // Carica dati intervento
  const rI = await sbFetch(SUPA_URL + '/rest/v1/interventi_con_stato?id=eq.' + id + '&select=*', { headers: H });
  const dati = await rI.json();
  if (!dati.length) { alert('Intervento non trovato.'); return; }
  const i = dati[0];

  // Carica partecipanti dalla tabella intervento_volontari (con dati anagrafici)
  let partecipanti = [];
  try {
    const rIV = await sbFetch(SUPA_URL + '/rest/v1/intervento_volontari?intervento_id=eq.' + id + '&select=volontario_id,art_39,data_inizio,data_fine,volontario:volontario_id(cognome,nome,luogo_nascita,data_nascita,codice_fiscale,telefono,email,citta)&order=id', { headers: H });
    partecipanti = await rIV.json();
  } catch(e) {}

  // Fallback legacy: se vuoto e ci sono volontari_ids
  if ((!partecipanti || !partecipanti.length) && i.volontari_ids && i.volontari_ids.length) {
    const rV = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=in.(' + i.volontari_ids.join(',') + ')&select=id,cognome,nome,luogo_nascita,data_nascita,codice_fiscale,telefono,email,citta&order=cognome', { headers: H });
    const vols = await rV.json();
    partecipanti = vols.map(v => ({
      volontario_id: v.id,
      art_39: false,
      data_inizio: i.data || null,
      data_fine: i.data_fine || i.data || null,
      volontario: v
    }));
  }

  // Carica il template
  const wb = new ExcelJS.Workbook();
  const buf = _b64ToArrayBuffer(MODULO_TERRITORIALE_B64);
  await wb.xlsx.load(buf);
  const ws = wb.getWorksheet('Foglio1') || wb.worksheets[0];

  // Compila intestazione
  const fmtIT = (d) => {
    if (!d) return '';
    const dd = new Date(d);
    return ('0' + dd.getDate()).slice(-2) + '/' + ('0' + (dd.getMonth()+1)).slice(-2) + '/' + dd.getFullYear();
  };
  ws.getCell('A6').value = 'EVENTO: ' + (i.evento || '');
  const dataStr = fmtIT(i.data) + (i.data_fine && i.data_fine !== i.data ? ' - ' + fmtIT(i.data_fine) : '');
  ws.getCell('A7').value = 'DATA: ' + dataStr;
  ws.getCell('A8').value = 'LOCALITA’: ' + (i.luogo || '');
  // A9 ASSOCIAZIONE GRUPPO e A10 ORARIO li lascio come sono

  // Compila riga per riga i volontari (parte dalla riga 15)
  const startRow = 15;
  partecipanti.forEach((p, idx) => {
    const r = startRow + idx;
    if (r > 28) return; // template max 14 righe (15-28)
    const v = p.volontario || {};
    ws.getCell('A' + r).value = (v.cognome || '').toUpperCase();
    ws.getCell('B' + r).value = (v.nome || '').toUpperCase();
    ws.getCell('C' + r).value = v.luogo_nascita || '';
    ws.getCell('D' + r).value = '';
    ws.getCell('E' + r).value = v.data_nascita ? fmtIT(v.data_nascita) : '';
    ws.getCell('F' + r).value = (v.codice_fiscale || '').toUpperCase();
    ws.getCell('G' + r).value = v.telefono || '';
    ws.getCell('H' + r).value = v.email || '';
    ws.getCell('I' + r).value = p.art_39 ? 'SI' : 'NO';
    ws.getCell('J' + r).value = p.data_inizio ? fmtIT(p.data_inizio) : (i.data ? fmtIT(i.data) : '');
    ws.getCell('K' + r).value = p.data_fine ? fmtIT(p.data_fine) : (i.data_fine ? fmtIT(i.data_fine) : (i.data ? fmtIT(i.data) : ''));
  });

  // Scarica
  const out = await wb.xlsx.writeBuffer();
  const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const safeName = (i.evento || 'modulo').replace(/[^A-Za-z0-9_\-]/g, '_').slice(0, 40);
  a.href = url;
  a.download = 'ModuloTerritoriale_' + safeName + '.xlsx';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}


async function stampaIntervento(id) {
  // Carica i dati dell'intervento
  var res = await sbFetch(SUPA_URL + '/rest/v1/interventi_con_stato?id=eq.' + id + '&select=*', { headers: H });
  var dati = await res.json();
  if (!dati.length) return;
  var i = dati[0];

  // Carica volontari con CF
  var volIds = i.volontari_ids || [];
  var vols = [];
  if (volIds.length) {
    var rv = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=in.(' + volIds.join(',') + ')&select=id,cognome,nome,codice_fiscale&order=cognome', { headers: H });
    vols = await rv.json();
  }

  var ora    = new Date().toLocaleString('it-IT');
  var data   = i.data ? new Date(i.data).toLocaleDateString('it-IT', { day:'2-digit', month:'long', year:'numeric' }) : '—';
  var dataF  = i.data_fine ? new Date(i.data_fine).toLocaleDateString('it-IT', { day:'2-digit', month:'long', year:'numeric' }) : null;

  var win = window.open('', '_blank');
  win.document.write('<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8">'
    + '<title>Intervento — ' + (i.evento||'—') + '</title>'
    + '<style>'
    + 'body{font-family:Arial,sans-serif;font-size:10pt;color:#111;margin:1.5cm;max-width:18cm}'
    + '.header{border-bottom:3px solid #1a7a4a;padding-bottom:0.8rem;margin-bottom:1rem}'
    + 'h1{font-size:14pt;color:#1a7a4a;margin:0 0 0.2rem}'
    + '.meta{font-size:8pt;color:#666}'
    + 'h2{font-size:10pt;font-weight:700;color:#1a7a4a;border-bottom:1px solid #e5e7eb;padding-bottom:4px;margin:1rem 0 0.5rem}'
    + 'table{width:100%;border-collapse:collapse;font-size:9pt}'
    + 'td,th{padding:5px 8px;border:0.5px solid #e5e7eb;text-align:left}'
    + 'th{background:#1a7a4a;color:white;font-weight:700}'
    + 'tr:nth-child(even) td{background:#f9fafb}'
    + '.info-table td:first-child{font-weight:600;color:#555;width:35%;background:#f9fafb}'
    + '.no-cf{color:#999;font-style:italic}'
    + '@media print{body{margin:1cm}th{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'
    + '</style></head><body>'
    + _headerHtmlCartaIntestata()
    + '<div class="header">'
    + '<h1>Intervento — ' + (i.evento||'—') + '</h1>'
    + '<div class="meta">Generato il ' + ora + '</div>'
    + '</div>'
    + '<h2>Dati intervento</h2>'
    + '<table class="info-table"><tbody>'
    + '<tr><td>Evento</td><td>' + (i.evento||'—') + '</td></tr>'
    + '<tr><td>Tipo attività</td><td>' + (i.tipo_attivita||'—') + '</td></tr>'
    + '<tr><td>Data inizio</td><td>' + data + '</td></tr>'
    + (dataF ? '<tr><td>Data fine</td><td>' + dataF + '</td></tr>' : '')
    + '<tr><td>Ore</td><td>' + (i.n_ore||'—') + '</td></tr>'
    + '<tr><td>N° volontari</td><td>' + (i.n_volontari||vols.length) + '</td></tr>'
    + '<tr><td>Registrato da</td><td>' + (i.utente||'—') + '</td></tr>'
    + (i.note ? '<tr><td>Note</td><td>' + i.note + '</td></tr>' : '')
    + '</tbody></table>'
    + '<h2>Volontari partecipanti (' + vols.length + ')</h2>'
    + '<table><thead><tr><th>#</th><th>Cognome e Nome</th><th>Codice Fiscale</th></tr></thead><tbody>'
    + vols.map(function(v, idx) {
        var cf = v.codice_fiscale ? v.codice_fiscale : '<span class="no-cf">non inserito</span>';
        return '<tr><td>' + (idx+1) + '</td><td>' + v.cognome + ' ' + v.nome + '</td><td>' + cf + '</td></tr>';
      }).join('')
    + '</tbody></table>'
    + '<div style="margin-top:2rem;display:grid;grid-template-columns:1fr 1fr;gap:2rem">'
    + '<div style="border-top:0.5px solid #111;padding-top:4px;font-size:8pt;color:#666;text-align:center;margin-top:2rem">Responsabile intervento</div>'
    + '<div style="border-top:0.5px solid #111;padding-top:4px;font-size:8pt;color:#666;text-align:center;margin-top:2rem">Coordinatore PC ANA Casale</div>'
    + '</div>'
    + '<script>window.onload=function(){setTimeout(function(){window.print();},400);}<\/script>'
    + '</body></html>');
  win.document.close();
}



// ============================================================
// LETTERA ATTIVAZIONE ART. 39 D.LGS 1/2018 (datore di lavoro)
// ============================================================

const LOGO_ANA_B64 = '';
const LOGO_VOL_B64 = '';

let _letteraAttVolId = null;

async function apriModalLetteraAttivazione(volontarioId) {
  if (!intCorrenteId) { alert('Salva prima l\'intervento.'); return; }
  _letteraAttVolId = volontarioId;

  // Carica dati volontario (inclusi campi ditta)
  let v;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + volontarioId + '&select=id,cognome,nome,datore_lavoro,indirizzo_lavoro,cap_lavoro,citta_lavoro', { headers: H });
    const arr = await r.json();
    v = arr[0];
  } catch(e) { alert('Errore caricamento dati volontario.'); return; }
  if (!v) { alert('Volontario non trovato.'); return; }

  const dataFineVal = document.getElementById('ifDataFine') ? document.getElementById('ifDataFine').value : '';
  const hasDataFine = !!dataFineVal;

  const overlay = document.createElement('div');
  overlay.id = 'letteraAttOverlay';
  overlay.className = 'ov';
  overlay.innerHTML = `
    <div class="sheet" role="dialog" aria-modal="true" aria-label="Lettera di attivazione">
      <div class="shead"><h2>Lettera di attivazione</h2><button class="x" onclick="document.getElementById('letteraAttOverlay').remove()" aria-label="Chiudi"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button></div>
      <div class="sbody form">
        <p class="note m0">${v.cognome} ${v.nome} — Art. 39 D.Lgs 1/2018</p>
        <label>Ragione sociale ditta *<input id="latDatoreLavoro" value="${v.datore_lavoro || ''}" placeholder="es. EPTA SPA"></label>
        <label>Indirizzo ditta<input id="latIndirizzoLavoro" value="${v.indirizzo_lavoro || ''}" placeholder="es. Via Achille Grandi 43"></label>
        <div class="row2">
          <label>CAP<input id="latCapLavoro" value="${v.cap_lavoro || ''}" placeholder="15033"></label>
          <label>Città<input id="latCittaLavoro" value="${v.citta_lavoro || ''}" placeholder="Casale Monferrato"></label>
        </div>
        <label class="chk${hasDataFine ? '' : ' lat-off'}"><input type="checkbox" id="latIncludiDataFine" ${hasDataFine ? '' : 'disabled'}> Includi data fine nel periodo di attivazione</label>
        ${hasDataFine ? '' : '<p class="note m0">Data fine non impostata sull\'intervento.</p>'}
        <div class="actions">
          <button type="button" class="btn" onclick="document.getElementById('letteraAttOverlay').remove()">Annulla</button>
          <button type="button" class="btn pri" onclick="generaLetteraAttivazione()">Genera PDF</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);
}

function _fmtITdata(d) {
  if (!d) return '';
  const parts = d.split('-');
  if (parts.length !== 3) return d;
  return parts[2] + '/' + parts[1] + '/' + parts[0];
}

async function generaLetteraAttivazione() {
  const volId = _letteraAttVolId;
  const datore   = document.getElementById('latDatoreLavoro').value.trim();
  const indirizzo = document.getElementById('latIndirizzoLavoro').value.trim();
  const cap       = document.getElementById('latCapLavoro').value.trim();
  const citta     = document.getElementById('latCittaLavoro').value.trim();
  const includiDataFine = document.getElementById('latIncludiDataFine').checked;

  if (!datore) { alert('Inserisci almeno la ragione sociale della ditta.'); return; }

  // Salva i dati ditta sul volontario (persistenza per usi futuri)
  try {
    await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + volId, {
      method: 'PATCH',
      headers: Object.assign({}, HJ, {'Prefer':'return=minimal'}),
      body: JSON.stringify({
        datore_lavoro: datore || null,
        indirizzo_lavoro: indirizzo || null,
        cap_lavoro: cap || null,
        citta_lavoro: citta || null
      })
    });
  } catch(e) { /* non bloccante: si procede comunque alla generazione */ }

  // Recupera dati volontario e intervento
  let v;
  try {
    const r = await sbFetch(SUPA_URL + '/rest/v1/volontari?id=eq.' + volId + '&select=cognome,nome', { headers: H });
    v = (await r.json())[0];
  } catch(e) { alert('Errore recupero dati volontario.'); return; }
  if (!v) { alert('Dati del volontario non disponibili.'); return; }

  const evento = (document.getElementById('ifEvento') || {}).value || '';
  const dataInizio = (document.getElementById('ifData') || {}).value || '';
  const dataFine = (document.getElementById('ifDataFine') || {}).value || '';

  const oggi = new Date();
  const oggiStr = String(oggi.getDate()).padStart(2,'0') + '/' + String(oggi.getMonth()+1).padStart(2,'0') + '/' + oggi.getFullYear();

  let periodoStr = 'dal ' + _fmtITdata(dataInizio);
  if (includiDataFine && dataFine) periodoStr += ' al ' + _fmtITdata(dataFine);
  else periodoStr += ' e sino cessate esigenze';

  document.getElementById('letteraAttOverlay').remove();
  _generaPdfLetteraAttivazione({
    nomeCompleto: (v.cognome || '').toUpperCase() + ' ' + (v.nome || '').toUpperCase(),
    datore, indirizzo, cap, citta,
    evento, dataEventoStr: _fmtITdata(dataInizio), periodoStr,
    oggiStr
  });
}

function _generaPdfLetteraAttivazione(d) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const marginL = 15, marginR = 15;
  const usableW = pw - marginL - marginR;

  // Loghi
  try { doc.addImage('data:image/png;base64,' + LOGO_ANA_B64, 'PNG', marginL, 12, 20, 20); } catch(e) {}
  try { doc.addImage('data:image/png;base64,' + LOGO_VOL_B64, 'PNG', pw - marginR - 16, 10, 16, 20.5); } catch(e) {}

  // Intestazione
  doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text('UNITÀ DI PROTEZIONE CIVILE A.N.A.', pw/2, 16, { align: 'center' });
  doc.text('SEZIONE DI CASALE MONFERRATO', pw/2, 21, { align: 'center' });
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
  doc.text('Medaglia d\'Oro al M.C. della Città di Casale Monferrato', pw/2, 26, { align: 'center' });

  doc.setFontSize(8);
  doc.text('Via T. de Cristoforis 16 • 15033 Casale Monferrato', pw/2, 31, { align: 'center' });
  doc.text('Presidente: Gian Luigi Ravera Cell. 3394159256 • presidente.casale@ana.it', pw/2, 35, { align: 'center' });
  doc.text('Coordinatore: Federico Bechis Cell. 3382479991 • pc.casale@ana.it', pw/2, 39, { align: 'center' });

  doc.setLineWidth(0.3);
  doc.line(marginL, 42, pw - marginR, 42);

  let y = 55;

  // Destinatario
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  doc.text('SPETT. LE', pw - marginR, y, { align: 'right' }); y += 5;
  doc.setFont('helvetica', 'bold');
  doc.text((d.datore || '').toUpperCase(), pw - marginR, y, { align: 'right' }); y += 5;
  doc.setFont('helvetica', 'normal');
  if (d.indirizzo) { doc.text(d.indirizzo, pw - marginR, y, { align: 'right' }); y += 5; }
  if (d.cap || d.citta) { doc.text(((d.cap || '') + ' ' + (d.citta || '')).trim(), pw - marginR, y, { align: 'right' }); y += 5; }

  y += 10;

  doc.setFontSize(10);
  const corpo1 = 'Si comunica che il vostro dipendente, ' + d.nomeCompleto + ', iscritto all\'organizzazione di Protezione civile denominata ASSOCIAZIONE NAZIONALE ALPINI SEZIONE DI CASALE MONFERRATO, facente parte del COORDINAMENTO TERRITORIALE DI ALESSANDRIA, sarà impiegato in occasione delle attività previste nell\'ambito dell\'evento ' + (d.evento || '') + (d.dataEventoStr ? (' il ' + d.dataEventoStr) : '') + ' in qualità di Volontario.';
  const corpo2 = 'Pertanto, nella data ' + d.periodoStr + ' non potrà presentarsi regolarmente in servizio presso di voi, godendo del diritto alla conservazione del posto di lavoro ed al mantenimento del trattamento economico e previdenziale ai sensi di quanto previsto dall\'art.39 D.L.G.S. 1/2018.';
  const corpo3 = 'Codesta ditta potrà chiedere il rimborso degli emolumenti versati al lavoratore per il periodo di assenza dal posto di lavoro, presentando domanda alla:';

  const lines1 = doc.splitTextToSize(corpo1, usableW);
  doc.text(lines1, marginL, y); y += lines1.length * 5 + 6;

  const lines2 = doc.splitTextToSize(corpo2, usableW);
  doc.text(lines2, marginL, y); y += lines2.length * 5 + 6;

  const lines3 = doc.splitTextToSize(corpo3, usableW);
  doc.text(lines3, marginL, y); y += lines3.length * 5 + 6;

  doc.text('REGIONE PIEMONTE', marginL, y); y += 5;
  doc.text('Direzione Opere Pubbliche', marginL, y); y += 5;
  doc.text('Settore Protezione Civile', marginL, y); y += 5;
  doc.text('C.so Marche 79', marginL, y); y += 5;
  doc.text('10146 - Torino', marginL, y); y += 9;

  const corpo4 = 'compilando l\'apposito modello scaricabile dall\'area download dell\'applicativo Volter, oppure dal sito internet della Regione Piemonte, Settore di Protezione Civile: http://www2.regione.piemonte.it/protezionecivile/index.php/volontariato/2-non-categorizzato/57-rimborsi-volontariato-d-p-r-194-01 ai fini della protocollazione, le domande compilate dovranno essere inviate via posta o per posta certificata al seguente indirizzo: protezione.civile@cert.regione.piemonte.it';
  const lines4 = doc.splitTextToSize(corpo4, usableW);
  doc.text(lines4, marginL, y); y += lines4.length * 5 + 8;

  doc.text('Per maggiori informazioni:', marginL, y); y += 5;
  doc.text('Regione Piemonte uff. volontariato: tel. 011.4326641 - 011.4326628 - 011.4326608', marginL, y); y += 5;
  doc.text('Si allega lettera di attivazione e concessione benefici della Regione Piemonte.', marginL, y); y += 10;

  doc.text('Colgo l\'occasione per porgere cordiali saluti.', marginL, y); y += 12;

  doc.text('Casale Monferrato, ' + d.oggiStr, marginL, y); y += 16;

  doc.text('In Fede', pw - marginR - 25, y, { align: 'center' }); y += 5;
  doc.text('Il Presidente', pw - marginR - 25, y, { align: 'center' }); y += 5;
  doc.text('Gian Luigi RAVERA', pw - marginR - 25, y, { align: 'center' });

  const nomeFile = 'Lettera_attivazione_' + d.nomeCompleto.replace(/\s+/g, '_') + '.pdf';
  doc.save(nomeFile);
}
